import { Emotion } from '../../../motion-emotion-interfaces/emotion.js';
import { Phase } from '../../../motion-emotion-interfaces/phase.js';
import { Particle } from '../../../motion-emotion-interfaces/particle.js';

class Tenderness extends Emotion {
  constructor(phases, opts = {}) {
    super(phases, opts);
  }

  decorate(entity, dt) {
    const e = entity.energy;
    const breathCycle = entity.t * 12 * Math.PI;
    const breathAmp = 0.05 * e;

    entity.radius = entity.baseRadius * (1.0 + breathAmp * Math.sin(breathCycle));

    const squash = 0.04 * e * Math.sin(breathCycle);
    entity.sx = 1.0 + squash;
    entity.sy = 1.0 - squash * 0.6;

    if (Math.random() < 0.06 * e) {
      const angle = Math.random() * Math.PI * 2;
      const p = new Particle('warmGlow', entity);
      p.x = entity.x + Math.cos(angle) * entity.radius * 0.6;
      p.y = entity.y + Math.sin(angle) * entity.radius * 0.6;
      p.vx = Math.cos(angle) * 10 * e;
      p.vy = Math.sin(angle) * 10 * e - 6;
      p.life = 1.0;
      p.decay = 0.35 + Math.random() * 0.25;
      p.radius = 1.5 + Math.random() * 2.5;
      entity.particles.push(p);
    }
  }
}

/** The shape begins in the upper-left quadrant, hovering with a slow breathing pulse.
 * It then drifts along a gentle downward curve toward the center-right of the canvas —
 * unhurried, as if drawn by something fragile. Upon arriving near center, it begins a
 * slow elliptical orbit, rocking gently like cradling — the radius softly expands and
 * contracts in rhythm. The orbit traces a warm path around a focal point just below
 * canvas center, with subtle squash-stretch aligned to the rocking direction. Faint
 * particles drift upward like warmth radiating from the shape. Finally the orbit
 * tightens to near-stillness as the shape settles just below center, expanding slightly
 * in radius — a relaxed exhale — with only a delicate breathing pulse remaining. The
 * entire sequence is slow, curved, and deliberate, reading as careful protective
 * closeness rather than stillness or passivity. */
export const gentleCradling = new Tenderness([
  new Phase({
    name: 'notice',
    description: 'Shape rests in upper-left quadrant with gentle breathing, then begins a slow curved drift toward center, as if noticing something precious and being drawn toward it',
    from: 0.0,
    to: 0.25,
    onEnter(entity, bounds) {
      const w = bounds.right - bounds.left;
      const h = bounds.bottom - bounds.top;
      entity._tStartX = bounds.left + w * 0.22;
      entity._tStartY = bounds.top + h * 0.20;
      entity._tMidX = bounds.left + w * 0.55;
      entity._tMidY = bounds.top + h * 0.35;
      entity._tCenterX = bounds.left + w * 0.5;
      entity._tCenterY = bounds.top + h * 0.53;
      entity._tCradleRadiusX = w * 0.14;
      entity._tCradleRadiusY = h * 0.08;
      entity._tCradleAngle = 0;
      entity._tRestX = bounds.left + w * 0.5;
      entity._tRestY = bounds.top + h * 0.55;

      entity.x = entity._tStartX;
      entity.y = entity._tStartY;
      entity.vx = 0;
      entity.vy = 0;
    },
    update(entity, dt, t) {
      const phaseT = Math.max(0, (t - 0.0) / 0.25);
      const ease = phaseT * phaseT * (3 - 2 * phaseT);

      const targetX = entity._tStartX + (entity._tMidX - entity._tStartX) * ease;
      const targetY = entity._tStartY + (entity._tMidY - entity._tStartY) * ease;

      const curveOffset = Math.sin(ease * Math.PI) * 30;
      const finalX = targetX + curveOffset;
      const finalY = targetY - curveOffset * 0.4;

      const stiffness = 2.0;
      const damping = 4.0;
      entity.vx += (finalX - entity.x) * stiffness * dt * 60 - entity.vx * damping * dt;
      entity.vy += (finalY - entity.y) * stiffness * dt * 60 - entity.vy * damping * dt;
      entity.x += entity.vx * dt;
      entity.y += entity.vy * dt;

      entity.orientation = Math.atan2(entity.vy, entity.vx);
    },
  }),

  new Phase({
    name: 'drift',
    description: 'Long gentle arc from mid-canvas down toward center, floating with barely perceptible stretch in direction of travel — the motion reads as calm purposeful approach',
    from: 0.25,
    to: 0.50,
    update(entity, dt, t) {
      const phaseT = Math.max(0, (t - 0.25) / 0.25);
      const ease = phaseT * phaseT * (3 - 2 * phaseT);

      const startX = entity._tMidX;
      const startY = entity._tMidY;
      const endX = entity._tCenterX + entity._tCradleRadiusX;
      const endY = entity._tCenterY;

      const arcBow = Math.sin(ease * Math.PI) * 50;

      const targetX = startX + (endX - startX) * ease + arcBow * 0.3;
      const targetY = startY + (endY - startY) * ease + arcBow * 0.6;

      const stiffness = 1.8;
      const damping = 3.5;
      entity.vx += (targetX - entity.x) * stiffness * dt * 60 - entity.vx * damping * dt;
      entity.vy += (targetY - entity.y) * stiffness * dt * 60 - entity.vy * damping * dt;
      entity.x += entity.vx * dt;
      entity.y += entity.vy * dt;

      const speed = Math.sqrt(entity.vx * entity.vx + entity.vy * entity.vy);
      entity.orientation = Math.atan2(entity.vy, entity.vx);

      const stretchAmt = Math.min(speed * 0.003, 0.08) * entity.energy;
      entity.sx = 1.0 + stretchAmt;
      entity.sy = 1.0 - stretchAmt * 0.5;

      entity.radius = entity.baseRadius * (1.0 + 0.05 * ease * entity.energy);
    },
  }),

  new Phase({
    name: 'cradle',
    description: 'Slow elliptical orbit around a point just below canvas center — gentle rocking motion like cradling, with radius pulsing in sync and warmth particles drifting upward',
    from: 0.50,
    to: 0.82,
    onEnter(entity) {
      entity._tCradleAngle = 0;
    },
    update(entity, dt, t) {
      const phaseT = Math.max(0, (t - 0.50) / 0.32);
      const e = entity.energy;

      const orbitsTotal = 2.2;
      entity._tCradleAngle = phaseT * orbitsTotal * Math.PI * 2;

      const shrinkFactor = 1.0 - phaseT * 0.35;
      const rx = entity._tCradleRadiusX * shrinkFactor;
      const ry = entity._tCradleRadiusY * shrinkFactor;

      const targetX = entity._tCenterX + Math.cos(entity._tCradleAngle) * rx;
      const targetY = entity._tCenterY + Math.sin(entity._tCradleAngle) * ry;

      const stiffness = 3.0;
      const damping = 5.0;
      entity.vx += (targetX - entity.x) * stiffness * dt * 60 - entity.vx * damping * dt;
      entity.vy += (targetY - entity.y) * stiffness * dt * 60 - entity.vy * damping * dt;
      entity.x += entity.vx * dt;
      entity.y += entity.vy * dt;

      const rockAngle = entity._tCradleAngle;
      const tiltAmt = 0.15 * e * shrinkFactor;
      entity.orientation = Math.sin(rockAngle) * tiltAmt;

      const rockStretch = 0.06 * e * shrinkFactor;
      entity.sx = 1.0 + rockStretch * Math.cos(rockAngle);
      entity.sy = 1.0 - rockStretch * Math.cos(rockAngle) * 0.5;

      entity.radius = entity.baseRadius * (1.0 + 0.08 * e);

      if (Math.random() < 0.12 * e) {
        const angle = Math.random() * Math.PI * 2;
        const p = new Particle('cradleWarmth', entity);
        p.x = entity.x + Math.cos(angle) * entity.radius * 1.2;
        p.y = entity.y + Math.sin(angle) * entity.radius * 1.2;
        p.vx = Math.cos(angle) * 6;
        p.vy = -8 - Math.random() * 6;
        p.life = 1.0;
        p.decay = 0.3 + Math.random() * 0.2;
        p.radius = 2 + Math.random() * 3;
        entity.particles.push(p);
      }
    },
    draw(ctx, entity) {
      const e = entity.energy;
      if (e < 0.1) return;
      ctx.save();
      ctx.globalAlpha = 0.06 * e;
      ctx.beginPath();
      ctx.arc(entity.x, entity.y, entity.radius * 2.2, 0, Math.PI * 2);
      ctx.fillStyle = '#ffffff';
      ctx.fill();
      ctx.restore();
    },
  }),

  new Phase({
    name: 'hold',
    description: 'Orbit contracts to near-stillness as the shape settles just below center, radius expands gently like a relaxed exhale, only delicate breathing pulse remains',
    from: 0.82,
    to: 1.0,
    update(entity, dt, t) {
      const phaseT = Math.max(0, (t - 0.82) / 0.18);
      const ease = phaseT * phaseT * (3 - 2 * phaseT);
      const e = entity.energy;

      const targetX = entity._tRestX;
      const targetY = entity._tRestY;

      const stiffness = 2.5;
      const damping = 6.0;
      entity.vx += (targetX - entity.x) * stiffness * dt * 60 - entity.vx * damping * dt;
      entity.vy += (targetY - entity.y) * stiffness * dt * 60 - entity.vy * damping * dt;
      entity.x += entity.vx * dt;
      entity.y += entity.vy * dt;

      entity.radius = entity.baseRadius * (1.0 + 0.12 * e * ease);

      entity.orientation *= (1.0 - ease);

      const breathCycle = t * 14 * Math.PI;
      const breathScale = 0.03 * e * (1.0 - ease * 0.5);
      entity.sx = 1.0 + breathScale * Math.sin(breathCycle);
      entity.sy = 1.0 - breathScale * Math.sin(breathCycle) * 0.6;
    },
    draw(ctx, entity) {
      const e = entity.energy;
      const phaseT = Math.max(0, (entity.t - 0.82) / 0.18);
      if (e < 0.1) return;
      ctx.save();
      ctx.globalAlpha = 0.04 * e * (1.0 - phaseT);
      ctx.beginPath();
      ctx.arc(entity.x, entity.y, entity.radius * 2.5, 0, Math.PI * 2);
      ctx.fillStyle = '#ffffff';
      ctx.fill();
      ctx.restore();
    },
  }),
], {
  energyFunction: t => {
    if (t < 0.25) return 0.3 + 0.3 * (t / 0.25);
    if (t < 0.50) return 0.6 + 0.1 * ((t - 0.25) / 0.25);
    if (t < 0.82) return 0.7;
    return 0.7 - 0.3 * ((t - 0.82) / 0.18);
  },
});