import { Emotion } from '../../../motion-emotion-interfaces/emotion.js';
import { Phase } from '../../../motion-emotion-interfaces/phase.js';
import { Particle } from '../../../motion-emotion-interfaces/particle.js';

class PanicMote extends Particle {
  constructor(entity) {
    super('panicMote', entity);
    this.life = 0.2 + Math.random() * 0.25;
    this.maxLife = this.life;
    const angle = Math.random() * Math.PI * 2;
    const speed = 60 + Math.random() * 100;
    this.pvx = Math.cos(angle) * speed;
    this.pvy = Math.sin(angle) * speed;
    this.ox = (Math.random() - 0.5) * entity.radius * 1.6;
    this.oy = (Math.random() - 0.5) * entity.radius * 1.6;
    this.size = 1 + Math.random() * 2.5;
  }

  update(dt) {
    this.life -= dt;
    this.ox += this.pvx * dt;
    this.oy += this.pvy * dt;
    this.pvx *= 0.94;
    this.pvy *= 0.94;
    return this.life > 0;
  }

  draw(ctx, entity) {
    const alpha = (this.life / this.maxLife);
    ctx.globalAlpha = alpha * 0.5;
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(entity.x + this.ox, entity.y + this.oy, this.size * alpha, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1;
  }
}

class FearEmotion extends Emotion {
  constructor(phases, opts = {}) {
    super(phases, opts);
  }

  decorate(entity, dt) {
    const energy = entity.energy;
    const time = Date.now() / 1000;

    const trembleAmp = energy * 3.5;
    const trembleFreq = 22 + energy * 28;
    entity.x += Math.sin(time * trembleFreq) * trembleAmp * dt * 60;
    entity.y += Math.cos(time * trembleFreq * 1.37 + 1.7) * trembleAmp * dt * 60;

    const breathRate = 10 + energy * 14;
    const breathAmp = 0.015 + energy * 0.06;
    entity.sx *= (1.0 + Math.sin(time * breathRate) * breathAmp);
    entity.sy *= (1.0 - Math.sin(time * breathRate) * breathAmp * 0.7);

    if (energy > 0.55 && Math.random() < (energy - 0.4) * 0.4) {
      entity.particles.push(new PanicMote(entity));
    }
  }
}

/** The shape begins near center with a slow, uneasy drift punctuated by sudden small flinches in random
 * directions — orientation whips erratically as if scanning for a threat. The jitter escalates until a
 * sharp startle triggers a violent squash compression, immediately followed by a panicked bolt toward the
 * bottom-left corner at maximum speed, the shape stretching thin along its velocity vector. Once cornered
 * it presses tight against the walls, radius shrinking to half, trembling with intense high-frequency
 * vibration; it makes tiny panicked micro-darts along the walls but always snaps back into the corner.
 * After sustained cowering, it breaks loose in an erratic zigzag dash toward the opposite (top-right)
 * region, changing direction every few frames with wild lateral offsets — never a straight line, always
 * flinching. It then freezes abruptly mid-canvas, velocity snapping to zero, locked in place with a
 * residual high-frequency tremor that slowly decays to complete stillness at diminished size. */
export const skittish = new FearEmotion([
  new Phase({
    name: 'uneasy',
    description: 'Nervous drift near center with escalating jitter, rapid scanning orientation shifts, and sudden small flinches in random directions',
    from: 0, to: 0.2,
    onEnter(entity, bounds) {
      const cx = (bounds.left + bounds.right) / 2;
      const cy = (bounds.top + bounds.bottom) / 2;
      entity._fearCenter = { x: cx, y: cy };
      entity._fearCorner = {
        x: bounds.left + entity.baseRadius * 1.5,
        y: bounds.bottom - entity.baseRadius * 1.5
      };
      entity._fearOpposite = {
        x: bounds.right - entity.baseRadius * 2,
        y: bounds.top + entity.baseRadius * 2
      };
      entity._fearBounds = bounds;
      entity._fearFlinchTimer = 0;
      entity._fearZigTimer = 0;
      entity._fearZigTarget = null;
      entity._fearFrozen = false;
      entity._fearFreezePos = null;
      entity.x = cx + (Math.random() - 0.5) * 30;
      entity.y = cy + (Math.random() - 0.5) * 30;
      entity.vx = 0;
      entity.vy = 0;
    },
    update(entity, dt, t) {
      const phaseT = t / 0.2;
      const center = entity._fearCenter;
      const time = Date.now() / 1000;

      const driftRadius = 25 + phaseT * 35;
      const driftSpeed = 1.8 + phaseT * 2.5;
      const targetX = center.x + Math.sin(time * driftSpeed) * driftRadius;
      const targetY = center.y + Math.cos(time * driftSpeed * 0.73) * driftRadius;

      const dx = targetX - entity.x;
      const dy = targetY - entity.y;
      entity.vx += dx * 3.5 * dt;
      entity.vy += dy * 3.5 * dt;
      entity.vx *= 0.91;
      entity.vy *= 0.91;

      entity._fearFlinchTimer -= dt;
      if (entity._fearFlinchTimer <= 0) {
        entity._fearFlinchTimer = 0.35 - phaseT * 0.25 + Math.random() * 0.1;
        const flinchAngle = Math.random() * Math.PI * 2;
        const flinchForce = 35 + phaseT * 90;
        entity.vx += Math.cos(flinchAngle) * flinchForce;
        entity.vy += Math.sin(flinchAngle) * flinchForce;
      }

      entity.orientation = Math.sin(time * 9) * Math.PI * 0.4 + Math.cos(time * 14.3) * Math.PI * 0.3;

      entity.sx = 1.0;
      entity.sy = 1.0;
      entity.radius = entity.baseRadius * (0.9 + 0.1 * Math.sin(time * 6));
    }
  }),

  new Phase({
    name: 'bolt',
    description: 'Violent squash flinch followed by maximum-speed panicked flight to bottom-left corner, shape stretching along velocity vector',
    from: 0.2, to: 0.4,
    onEnter(entity) {
      entity._fearBoltStart = { x: entity.x, y: entity.y };
    },
    update(entity, dt, t) {
      const phaseT = (t - 0.2) / 0.2;
      const corner = entity._fearCorner;

      if (phaseT < 0.12) {
        const flinchT = phaseT / 0.12;
        const pulse = Math.sin(flinchT * Math.PI);
        entity.sx = 1.0 - 0.35 * pulse;
        entity.sy = 1.0 + 0.4 * pulse;
        entity.vx *= 0.7;
        entity.vy *= 0.7;
        return;
      }

      const boltT = (phaseT - 0.12) / 0.88;
      const accel = 0.3 + boltT * 0.7;

      const dx = corner.x - entity.x;
      const dy = corner.y - entity.y;
      const dist = Math.sqrt(dx * dx + dy * dy);

      if (dist > 4) {
        const speed = 350 + accel * 650;
        entity.vx += (dx / dist) * speed * dt * 10;
        entity.vy += (dy / dist) * speed * dt * 10;
      }

      entity.vx *= 0.88;
      entity.vy *= 0.88;

      const vel = Math.sqrt(entity.vx * entity.vx + entity.vy * entity.vy);
      if (vel > 15) {
        entity.orientation = Math.atan2(entity.vy, entity.vx);
        const s = Math.min(vel / 450, 0.4);
        entity.sx = 1.0 + s;
        entity.sy = 1.0 - s * 0.5;
      } else {
        entity.sx = 1.0;
        entity.sy = 1.0;
      }

      entity.radius = entity.baseRadius * (0.85 - boltT * 0.3);
    }
  }),

  new Phase({
    name: 'cower',
    description: 'Pressed deep into corner at shrunk radius, intense trembling, occasional tiny panicked darts along the walls that snap back to safety',
    from: 0.4, to: 0.7,
    update(entity, dt, t) {
      const phaseT = (t - 0.4) / 0.3;
      const corner = entity._fearCorner;
      const center = entity._fearCenter;
      const time = Date.now() / 1000;

      const dartCycle = Math.sin(time * 3.7) * Math.sin(time * 5.9);
      let dartX = 0;
      let dartY = 0;

      if (dartCycle > 0.65) {
        dartX = Math.sin(time * 14) * 50;
      } else if (dartCycle < -0.65) {
        dartY = Math.sin(time * 12) * 45;
      }

      const targetX = corner.x + dartX;
      const targetY = corner.y + dartY;

      const pullStrength = 12;
      entity.vx += (targetX - entity.x) * pullStrength * dt;
      entity.vy += (targetY - entity.y) * pullStrength * dt;
      entity.vx *= 0.82;
      entity.vy *= 0.82;

      entity.radius = entity.baseRadius * (0.45 + 0.08 * Math.sin(time * 22));

      entity.orientation = Math.atan2(
        corner.y - center.y,
        corner.x - center.x
      ) + Math.sin(time * 18) * 0.3;

      const flinchSx = Math.sin(time * 19) * 0.06;
      entity.sx = 1.0 + flinchSx;
      entity.sy = 1.0 - flinchSx * 0.5;
    }
  }),

  new Phase({
    name: 'scatter-freeze',
    description: 'Erratic zigzag dash across canvas toward opposite corner with sharp directional reversals, then abrupt freeze with high-frequency tremor decaying to total stillness at diminished size',
    from: 0.7, to: 1.0,
    onEnter(entity) {
      entity._fearZigTimer = 0;
      entity._fearZigTarget = { x: entity.x, y: entity.y };
      entity._fearFrozen = false;
      entity._fearFreezePos = null;
    },
    update(entity, dt, t) {
      const phaseT = (t - 0.7) / 0.3;
      const bounds = entity._fearBounds;
      const time = Date.now() / 1000;
      const corner = entity._fearCorner;
      const opposite = entity._fearOpposite;

      if (phaseT < 0.55) {
        const flightT = phaseT / 0.55;

        entity._fearZigTimer -= dt;
        if (entity._fearZigTimer <= 0) {
          entity._fearZigTimer = 0.06 + Math.random() * 0.1;

          const baseX = corner.x + (opposite.x - corner.x) * flightT;
          const baseY = corner.y + (opposite.y - corner.y) * flightT;

          const perpAngle = Math.atan2(
            opposite.y - corner.y,
            opposite.x - corner.x
          ) + Math.PI / 2;

          const lateralAmp = 130 * (1 - flightT * 0.6);
          const zigOffset = (Math.random() - 0.5) * 2 * lateralAmp;

          entity._fearZigTarget = {
            x: Math.max(bounds.left + 20, Math.min(bounds.right - 20, baseX + Math.cos(perpAngle) * zigOffset)),
            y: Math.max(bounds.top + 20, Math.min(bounds.bottom - 20, baseY + Math.sin(perpAngle) * zigOffset))
          };
        }

        const target = entity._fearZigTarget;
        const dx = target.x - entity.x;
        const dy = target.y - entity.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (dist > 2) {
          const speed = 450 + (1 - flightT) * 350;
          entity.vx += (dx / dist) * speed * dt * 12;
          entity.vy += (dy / dist) * speed * dt * 12;
        }

        entity.vx *= 0.88;
        entity.vy *= 0.88;

        const vel = Math.sqrt(entity.vx * entity.vx + entity.vy * entity.vy);
        if (vel > 20) {
          entity.orientation = Math.atan2(entity.vy, entity.vx);
          const s = Math.min(vel / 400, 0.35);
          entity.sx = 1.0 + s;
          entity.sy = 1.0 - s * 0.45;
        } else {
          entity.sx = 1.0;
          entity.sy = 1.0;
        }

        entity.radius = entity.baseRadius * (0.55 + flightT * 0.1);

      } else {
        if (!entity._fearFrozen) {
          entity._fearFrozen = true;
          entity._fearFreezePos = { x: entity.x, y: entity.y };
          entity.vx = 0;
          entity.vy = 0;
        }

        const freezeT = (phaseT - 0.55) / 0.45;
        const decay = Math.pow(1 - freezeT, 2);

        entity.x = entity._fearFreezePos.x;
        entity.y = entity._fearFreezePos.y;
        entity.vx = 0;
        entity.vy = 0;

        const tremorAmp = decay * 7;
        entity.x += Math.sin(time * 38) * tremorAmp;
        entity.y += Math.cos(time * 44) * tremorAmp;

        entity.sx = 1.0 + decay * 0.04 * Math.sin(time * 28);
        entity.sy = 1.0 - decay * 0.04 * Math.sin(time * 28);

        entity.radius = entity.baseRadius * (0.5 + freezeT * 0.2);

        entity.orientation += decay * Math.sin(time * 30) * 0.15;
      }
    },
    draw(ctx, entity) {
      if (entity._fearFrozen && entity._fearFreezePos) {
        const time = Date.now() / 1000;
        const phaseT = (entity.t - 0.7) / 0.3;
        const freezeT = Math.max(0, (phaseT - 0.55) / 0.45);
        const decay = Math.pow(1 - freezeT, 2);

        if (decay > 0.1) {
          ctx.save();
          ctx.strokeStyle = 'rgba(255,255,255,' + (decay * 0.15) + ')';
          ctx.lineWidth = 1;
          const r = entity.radius + 8 + decay * 12;
          for (let i = 0; i < 3; i++) {
            const offset = Math.sin(time * 25 + i * 2.1) * decay * 4;
            ctx.beginPath();
            ctx.arc(entity.x + offset, entity.y - offset, r + i * 5, 0, Math.PI * 2);
            ctx.stroke();
          }
          ctx.restore();
        }
      }
    }
  })
], {
  energyFunction: function(t) {
    if (t < 0.2) return 0.15 + 0.45 * (t / 0.2);
    if (t < 0.4) return 0.6 + 0.4 * ((t - 0.2) / 0.2);
    if (t < 0.7) return 0.8 + 0.2 * Math.sin(((t - 0.4) / 0.3) * Math.PI);
    const fadeT = (t - 0.7) / 0.3;
    if (fadeT < 0.55) return 0.75 + 0.15 * (1 - fadeT / 0.55);
    return 0.6 * Math.pow(1 - (fadeT - 0.55) / 0.45, 1.5);
  }
});