import { Emotion } from '../../../motion-emotion-interfaces/emotion.js';
import { Phase } from '../../../motion-emotion-interfaces/phase.js';
import { Particle } from '../../../motion-emotion-interfaces/particle.js';

class DisgustDroplet extends Particle {
  constructor(entity) {
    super('disgust_droplet', entity);
    this.life = 0.35 + Math.random() * 0.3;
    this.maxLife = this.life;
    const angle = Math.PI * 0.25 + Math.random() * Math.PI * 0.5;
    const speed = 20 + Math.random() * 50;
    this.vx = Math.cos(angle) * speed * (Math.random() < 0.5 ? -1 : 1);
    this.vy = Math.sin(angle) * speed;
    this.size = 1.5 + Math.random() * 2.5;
  }

  update(dt) {
    this.life -= dt;
    this.vy += 100 * dt;
    this.x += this.vx * dt;
    this.y += this.vy * dt;
    this.vx *= 0.97;
    this.alpha = Math.max(0, this.life / this.maxLife) * 0.7;
    return this.life > 0;
  }
}

class Disgust extends Emotion {
  constructor(phases, opts = {}) {
    super(phases, opts);
  }

  decorate(entity, dt) {
    const energy = entity.energy;

    const queasyCycle = Math.sin(entity.t * Math.PI * 18) * energy;
    entity.sx += queasyCycle * 0.025;
    entity.sy -= queasyCycle * 0.025;

    if (entity.t > 0.2 && entity.t < 0.7) {
      const intensity = energy * 2.5;
      entity.x += (Math.random() - 0.5) * intensity;
      entity.y += (Math.random() - 0.5) * intensity;
    }
  }
}

/**
 * The shape creeps cautiously from the bottom edge toward center, decelerating as
 * unease mounts — radius subtly contracts and a slight vertical squash signals growing
 * nausea. Upon reaching roughly 70% of the way to center it recoils violently backward,
 * squashing flat and stretching tall in a sharp flinch, snapping away ~180px along the
 * retreat vector while shedding dripping particles. The heaving phase follows: the shape
 * drifts laterally while convulsing with rapid decaying squash-stretch oscillations
 * (14 Hz decaying sine), radius pulsing smaller with each contraction, positional tremor
 * layered on top, particles dripping downward like something expelled. Finally the shape
 * averts — it creeps via smoothstep into the top-left corner, shrinking to 60% base
 * radius, orientation locked facing away from center, residual tremor fading, energy
 * draining to near-zero as it withdraws from engagement entirely.
 */
export const revulsion = new Disgust([
  new Phase({
    name: 'approach',
    description: 'Cautious creep from bottom edge toward center, decelerating — radius contracts slightly, vertical squash hints at rising nausea',
    from: 0, to: 0.2,
    onEnter(entity, bounds) {
      const cx = (bounds.left + bounds.right) / 2;
      const cy = (bounds.top + bounds.bottom) / 2;
      entity._disgustCenter = { x: cx, y: cy };
      entity._disgustStart = { x: cx + (Math.random() - 0.5) * 40, y: bounds.bottom - 60 };
      entity.x = entity._disgustStart.x;
      entity.y = entity._disgustStart.y;
      entity._disgustBaseRadius = entity.baseRadius;
      entity._disgustRetreatCorner = { x: bounds.left + 50, y: bounds.top + 50 };
      entity._disgustBounds = bounds;
    },
    update(entity, dt, t) {
      const phaseT = t / 0.2;
      const ease = 1 - Math.pow(1 - phaseT, 2);

      const sx = entity._disgustStart.x;
      const sy = entity._disgustStart.y;
      const cx = entity._disgustCenter.x;
      const cy = entity._disgustCenter.y;

      entity.x = sx + (cx - sx) * ease * 0.7;
      entity.y = sy + (cy - sy) * ease * 0.7;

      entity.sx = 1.0 - 0.06 * phaseT;
      entity.sy = 1.0 + 0.04 * phaseT;

      entity.radius = entity._disgustBaseRadius * (1.0 - 0.06 * phaseT);

      entity.vx = (cx - entity.x) * 0.4 * (1 - phaseT * 0.6);
      entity.vy = (cy - entity.y) * 0.4 * (1 - phaseT * 0.6);

      entity.orientation = Math.atan2(cy - entity.y, cx - entity.x);
    },
  }),
  new Phase({
    name: 'recoil',
    description: 'Violent backward jerk away from center — shape squashes flat and stretches tall at peak, snapping along retreat vector with expelled particles',
    from: 0.2, to: 0.38,
    onEnter(entity, bounds) {
      entity._disgustRecoilStart = { x: entity.x, y: entity.y };
      const cx = entity._disgustCenter.x;
      const cy = entity._disgustCenter.y;
      const dx = entity.x - cx;
      const dy = entity.y - cy;
      const dist = Math.sqrt(dx * dx + dy * dy) || 1;
      entity._disgustRecoilDir = { x: dx / dist, y: dy / dist };
    },
    update(entity, dt, t) {
      const phaseT = (t - 0.2) / 0.18;
      const recoilEase = 1 - Math.pow(1 - phaseT, 3);
      const recoilDist = 180;

      const ox = entity._disgustRecoilStart.x;
      const oy = entity._disgustRecoilStart.y;
      const dx = entity._disgustRecoilDir.x;
      const dy = entity._disgustRecoilDir.y;

      entity.x = ox + dx * recoilDist * recoilEase;
      entity.y = oy + dy * recoilDist * recoilEase;

      const squashPeak = Math.sin(phaseT * Math.PI);
      entity.sx = 1.0 - 0.35 * squashPeak;
      entity.sy = 1.0 + 0.4 * squashPeak;

      entity.radius = entity._disgustBaseRadius * (0.95 - 0.15 * squashPeak);

      entity.vx = dx * recoilDist * 3.5 * (1 - phaseT);
      entity.vy = dy * recoilDist * 3.5 * (1 - phaseT);

      entity.orientation = Math.atan2(dy, dx);

      if (phaseT < 0.6 && Math.random() < 0.5 * entity.energy) {
        entity.particles.push(new DisgustDroplet(entity));
      }
    },
    draw(ctx, entity) {
      const phaseT = Math.min(1, (entity.t - 0.2) / 0.18);
      if (phaseT < 0.5) {
        const alpha = (0.5 - phaseT) * 0.6 * entity.energy;
        const cx = entity._disgustCenter.x;
        const cy = entity._disgustCenter.y;
        const dx = entity.x - cx;
        const dy = entity.y - cy;
        const angle = Math.atan2(dy, dx);
        ctx.save();
        ctx.strokeStyle = `rgba(0,0,0,${alpha})`;
        ctx.lineWidth = 2;
        ctx.setLineDash([4, 8]);
        const len = 40 + 30 * entity.energy;
        for (let i = -1; i <= 1; i++) {
          const a = angle + i * 0.2;
          ctx.beginPath();
          ctx.moveTo(entity.x, entity.y);
          ctx.lineTo(entity.x + Math.cos(a) * len, entity.y + Math.sin(a) * len);
          ctx.stroke();
        }
        ctx.setLineDash([]);
        ctx.restore();
      }
    },
  }),
  new Phase({
    name: 'heave',
    description: 'Convulsive gagging oscillations — rapid decaying squash-stretch cycles with radius pulsing, lateral drift, positional tremor, and downward-dripping particles',
    from: 0.38, to: 0.7,
    onEnter(entity, bounds) {
      entity._disgustHeaveStart = { x: entity.x, y: entity.y };
      const corner = entity._disgustRetreatCorner;
      entity._disgustHeaveTarget = {
        x: entity.x + (corner.x - entity.x) * 0.55,
        y: entity.y + (corner.y - entity.y) * 0.55,
      };
    },
    update(entity, dt, t) {
      const phaseT = (t - 0.38) / 0.32;

      const ease = phaseT * phaseT;
      const ox = entity._disgustHeaveStart.x;
      const oy = entity._disgustHeaveStart.y;
      const tx = entity._disgustHeaveTarget.x;
      const ty = entity._disgustHeaveTarget.y;

      entity.x = ox + (tx - ox) * ease;
      entity.y = oy + (ty - oy) * ease;

      const heaveFreq = 14;
      const heaveDecay = 1 - phaseT * 0.65;
      const heave = Math.sin(phaseT * heaveFreq * Math.PI * 2) * heaveDecay;

      entity.sx = 1.0 + 0.28 * heave * entity.energy;
      entity.sy = 1.0 - 0.28 * heave * entity.energy;

      const radiusPulse = Math.abs(heave) * 0.12;
      entity.radius = entity._disgustBaseRadius * (0.82 - radiusPulse * entity.energy);

      entity.vx = heave * 35 * entity.energy;
      entity.vy = Math.abs(heave) * 25 * entity.energy;

      const tremor = heaveDecay * entity.energy;
      entity.x += Math.sin(phaseT * 47) * 2.5 * tremor;
      entity.y += Math.cos(phaseT * 43) * 2 * tremor;

      const cx = entity._disgustCenter.x;
      const cy = entity._disgustCenter.y;
      const awayAngle = Math.atan2(entity.y - cy, entity.x - cx);
      entity.orientation = awayAngle + heave * 0.2 * entity.energy;

      if (Math.random() < 0.28 * entity.energy * heaveDecay) {
        entity.particles.push(new DisgustDroplet(entity));
      }
    },
    draw(ctx, entity) {
      const phaseT = Math.min(1, (entity.t - 0.38) / 0.32);
      const heaveDecay = 1 - phaseT * 0.65;
      const wobbleAlpha = heaveDecay * entity.energy * 0.2;
      if (wobbleAlpha > 0.02) {
        ctx.save();
        ctx.strokeStyle = `rgba(0,0,0,${wobbleAlpha})`;
        ctx.lineWidth = 1;
        const r = entity.radius * 1.4;
        ctx.beginPath();
        for (let i = 0; i <= 20; i++) {
          const a = (i / 20) * Math.PI * 2;
          const wobble = Math.sin(a * 5 + entity.t * 30) * 4 * heaveDecay;
          const px = entity.x + Math.cos(a) * (r + wobble);
          const py = entity.y + Math.sin(a) * (r + wobble);
          if (i === 0) ctx.moveTo(px, py);
          else ctx.lineTo(px, py);
        }
        ctx.closePath();
        ctx.stroke();
        ctx.restore();
      }
    },
  }),
  new Phase({
    name: 'avert',
    description: 'Final retreat into far corner — shape shrinks steadily, orientation locked facing away from center, residual tremor fades, energy drains to near stillness as it withdraws',
    from: 0.7, to: 1.0,
    onEnter(entity, bounds) {
      entity._disgustAvertStart = { x: entity.x, y: entity.y };
      entity._disgustAvertOrientStart = entity.orientation;
    },
    update(entity, dt, t) {
      const phaseT = (t - 0.7) / 0.3;
      const ease = phaseT * phaseT * (3 - 2 * phaseT);

      const ox = entity._disgustAvertStart.x;
      const oy = entity._disgustAvertStart.y;
      const tx = entity._disgustRetreatCorner.x;
      const ty = entity._disgustRetreatCorner.y;

      entity.x = ox + (tx - ox) * ease;
      entity.y = oy + (ty - oy) * ease;

      const shrink = 1.0 - 0.35 * ease;
      entity.radius = entity._disgustBaseRadius * 0.82 * shrink;

      const residual = (1 - phaseT);
      entity.sx = 1.0 - 0.06 * residual;
      entity.sy = 1.0 + 0.04 * residual;

      entity.vx = (tx - entity.x) * 0.25 * residual;
      entity.vy = (ty - entity.y) * 0.25 * residual;

      const cx = entity._disgustCenter.x;
      const cy = entity._disgustCenter.y;
      entity.orientation = Math.atan2(entity.y - cy, entity.x - cx);

      const tremor = residual * 1.8 * entity.energy;
      entity.x += (Math.random() - 0.5) * tremor;
      entity.y += (Math.random() - 0.5) * tremor;

      if (Math.random() < 0.06 * entity.energy * residual) {
        entity.particles.push(new DisgustDroplet(entity));
      }
    },
  }),
], {
  energyFunction: t => {
    if (t < 0.2) return 0.15 + 0.35 * (t / 0.2);
    if (t < 0.38) return 0.5 + 0.5 * ((t - 0.2) / 0.18);
    if (t < 0.7) return 1.0 - 0.3 * ((t - 0.38) / 0.32);
    return 0.7 - 0.55 * ((t - 0.7) / 0.3);
  },
});