import { Emotion } from '../../../motion-emotion-interfaces/emotion.js';
import { Phase } from '../../../motion-emotion-interfaces/phase.js';

class Relaxed extends Emotion {
  constructor(phases, opts = {}) {
    super(phases, opts);
  }

  decorate(entity, dt) {
    const breathCycle = Math.sin(entity.t * Math.PI * 10);
    const intensity = entity.energy * 0.08;
    entity.radius = entity.baseRadius * (1.0 + intensity * breathCycle);

    const stretch = 0.04 * entity.energy * breathCycle;
    entity.sx = 1.0 + stretch;
    entity.sy = 1.0 - stretch;

    const speed = Math.sqrt(entity.vx * entity.vx + entity.vy * entity.vy);
    if (speed > 2) {
      const targetAngle = Math.atan2(entity.vy, entity.vx);
      let diff = targetAngle - entity.orientation;
      while (diff > Math.PI) diff -= Math.PI * 2;
      while (diff < -Math.PI) diff += Math.PI * 2;
      entity.orientation += diff * 1.2 * dt;
    }
  }
}

/** The shape begins with a slow, sighing descent from its starting position toward
 * the lower-center canvas, drifting laterally with a gentle sinusoidal sway as it
 * expands softly — like a body exhaling and sinking into warm water. Once settled,
 * it embarks on a wide, lazy elliptical orbit that spans roughly 75% of the canvas
 * width and visits both the upper and lower halves, with a subtle organic wobble
 * layered onto the vertical component so the path never feels mechanical. Speed is
 * capped low, steering is heavily damped, and a continuous breathing pulse gently
 * inflates and deflates the shape with matching squash-stretch throughout. In the
 * final phase the shape spirals inward toward the canvas center, its movement
 * reducing to a soft diminishing pendulum sway — rocking side to side with
 * shrinking amplitude until it arrives at near-stillness, only the faintest
 * breathing rhythm still visible. */
export const adrift = new Relaxed([
  new Phase({
    name: 'exhale',
    description: 'Gentle sighing descent toward lower-center with lateral sway and soft expansion, settling into comfort',
    from: 0, to: 0.2,
    onEnter(entity, bounds) {
      const cx = (bounds.left + bounds.right) / 2;
      const cy = (bounds.top + bounds.bottom) / 2;
      const w = bounds.right - bounds.left;
      const h = bounds.bottom - bounds.top;
      entity._adriftCx = cx;
      entity._adriftCy = cy;
      entity._adriftW = w;
      entity._adriftH = h;
      entity._adriftSettleTarget = { x: cx, y: cy + h * 0.15 };
      entity._adriftStartPos = { x: entity.x, y: entity.y };
    },
    update(entity, dt, t) {
      const phaseT = t / 0.2;
      const eased = phaseT * phaseT * (3 - 2 * phaseT);

      const start = entity._adriftStartPos;
      const target = entity._adriftSettleTarget;

      const goalX = start.x + (target.x - start.x) * eased;
      const goalY = start.y + (target.y - start.y) * eased;

      const swayX = Math.sin(phaseT * Math.PI * 2.5) * entity._adriftW * 0.06;

      const dx = (goalX + swayX) - entity.x;
      const dy = goalY - entity.y;

      entity.vx = dx * 2.5;
      entity.vy = dy * 2.5;

      entity.radius = entity.baseRadius * (1.0 + 0.12 * eased * entity.energy);
    },
  }),
  new Phase({
    name: 'float',
    description: 'Wide lazy elliptical orbit spanning the full canvas, organic wobble on the vertical axis, heavily damped steering',
    from: 0.2, to: 0.72,
    onEnter(entity) {
      entity._adriftFloatEntryX = entity.x;
      entity._adriftFloatEntryY = entity.y;
    },
    update(entity, dt, t) {
      const phaseT = (t - 0.2) / 0.52;
      const cx = entity._adriftCx;
      const cy = entity._adriftCy;
      const w = entity._adriftW;
      const h = entity._adriftH;

      const blendIn = Math.min(1, phaseT * 5);

      const angle = phaseT * Math.PI * 2;
      const pathX = cx + w * 0.38 * Math.cos(angle);
      const pathY = cy + h * 0.3 * Math.sin(angle)
                       + h * 0.06 * Math.sin(angle * 3 + 0.5);

      const targetX = entity._adriftFloatEntryX + (pathX - entity._adriftFloatEntryX) * blendIn;
      const targetY = entity._adriftFloatEntryY + (pathY - entity._adriftFloatEntryY) * blendIn;

      const dx = targetX - entity.x;
      const dy = targetY - entity.y;

      const damping = Math.pow(0.12, dt);
      entity.vx = entity.vx * damping + dx * 2.8 * (1 - damping);
      entity.vy = entity.vy * damping + dy * 2.8 * (1 - damping);

      const maxSpeed = 90 + 40 * entity.energy;
      const speed = Math.sqrt(entity.vx * entity.vx + entity.vy * entity.vy);
      if (speed > maxSpeed) {
        const scale = maxSpeed / speed;
        entity.vx *= scale;
        entity.vy *= scale;
      }

      entity.radius = entity.baseRadius * (1.06 + 0.06 * entity.energy);
    },
    draw(ctx, entity) {
      const alpha = 0.04 * entity.energy;
      if (alpha > 0.005) {
        ctx.beginPath();
        ctx.arc(entity.x, entity.y, entity.radius * 1.6, 0, Math.PI * 2);
        ctx.strokeStyle = `rgba(255,255,255,${alpha})`;
        ctx.lineWidth = 1;
        ctx.stroke();
      }
    },
  }),
  new Phase({
    name: 'lull',
    description: 'Gentle spiral inward to center with diminishing pendulum sway, arriving at near-stillness with only breathing visible',
    from: 0.72, to: 1.0,
    onEnter(entity) {
      entity._adriftLullStartX = entity.x;
      entity._adriftLullStartY = entity.y;
    },
    update(entity, dt, t) {
      const phaseT = (t - 0.72) / 0.28;
      const eased = phaseT * phaseT * (3 - 2 * phaseT);
      const cx = entity._adriftCx;
      const cy = entity._adriftCy;
      const w = entity._adriftW;

      const swayDecay = 1.0 - eased;
      const swayAmplitude = w * 0.18 * swayDecay * swayDecay;
      const swayX = Math.sin(phaseT * Math.PI * 5) * swayAmplitude;
      const swayY = Math.cos(phaseT * Math.PI * 3.5) * swayAmplitude * 0.25;

      const anchorX = entity._adriftLullStartX + (cx - entity._adriftLullStartX) * eased;
      const anchorY = entity._adriftLullStartY + (cy - entity._adriftLullStartY) * eased;

      const targetX = anchorX + swayX;
      const targetY = anchorY + swayY;

      const dx = targetX - entity.x;
      const dy = targetY - entity.y;

      const stiffness = 2.0 + 2.0 * eased;
      const damping = Math.pow(0.06, dt);
      entity.vx = entity.vx * damping + dx * stiffness * (1 - damping);
      entity.vy = entity.vy * damping + dy * stiffness * (1 - damping);

      const maxSpeed = 80 * (1.0 - 0.85 * eased);
      const speed = Math.sqrt(entity.vx * entity.vx + entity.vy * entity.vy);
      if (speed > maxSpeed) {
        const scale = maxSpeed / speed;
        entity.vx *= scale;
        entity.vy *= scale;
      }

      entity.radius = entity.baseRadius * (1.06 - 0.06 * eased + 0.03 * entity.energy);
    },
  }),
], {
  energyFunction: function (t) {
    if (t < 0.2) {
      return 0.45 + 0.1 * (t / 0.2);
    } else if (t < 0.72) {
      const mid = (t - 0.2) / 0.52;
      return 0.5 + 0.12 * Math.sin(mid * Math.PI);
    } else {
      const end = (t - 0.72) / 0.28;
      return 0.5 - 0.28 * end * end;
    }
  }
});