import { Emotion } from '../../../motion-emotion-interfaces/emotion.js';
import { Phase } from '../../../motion-emotion-interfaces/phase.js';
import { Particle } from '../../../motion-emotion-interfaces/particle.js';

class SparkParticle extends Particle {
  constructor(entity, biasX, biasY) {
    super('effervescentSpark', entity);
    this.x = entity.x;
    this.y = entity.y;
    const angle = Math.random() * Math.PI * 2;
    const speed = 30 + Math.random() * 90;
    this.vx = Math.cos(angle) * speed + (biasX || 0);
    this.vy = Math.sin(angle) * speed + (biasY || -50);
    this.life = 1.0;
    this.decay = 0.8 + Math.random() * 1.4;
    this.r = 1.5 + Math.random() * 3.5;
  }

  update(dt) {
    this.x += this.vx * dt;
    this.y += this.vy * dt;
    this.vy -= 35 * dt;
    this.vx *= 0.96;
    this.life -= this.decay * dt;
    return this.life > 0;
  }

  draw(ctx) {
    ctx.globalAlpha = Math.max(0, this.life) * 0.55;
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.r * Math.max(0, this.life), 0, Math.PI * 2);
    ctx.fill();
  }
}

function easeOut(t) { return t * (2 - t); }
function easeInOut(t) { return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; }
function lerp(a, b, t) { return a + (b - a) * t; }
function clamp01(t) { return Math.max(0, Math.min(1, t)); }

class Effervescent extends Emotion {
  constructor(phases, opts = {}) {
    super(phases, opts);
  }

  decorate(entity, dt) {
    const energy = entity.energy;
    const time = entity.t;

    const pulseRate = 7 + energy * 16;
    const pulse = Math.sin(time * Math.PI * pulseRate);
    entity.radius = entity.baseRadius * (1 + pulse * 0.18 * energy);

    const shimmer = energy * 2.2;
    entity.x += (Math.random() - 0.5) * shimmer;
    entity.y += (Math.random() - 0.5) * shimmer;

    const speed = Math.sqrt(entity.vx * entity.vx + entity.vy * entity.vy);
    if (speed > 20) {
      entity.orientation = Math.atan2(entity.vy, entity.vx);
      const stretch = Math.min(speed / 220, 0.55) * energy;
      entity.sx = 1 + stretch;
      entity.sy = 1 - stretch * 0.35;
    } else {
      const breathe = Math.sin(time * Math.PI * 9) * 0.12 * energy;
      entity.sx = 1 + breathe;
      entity.sy = 1 - breathe;
    }

    if (energy > 0.5 && Math.random() < (energy - 0.4) * 0.4) {
      entity.particles.push(new SparkParticle(entity, entity.vx * 0.15, entity.vy * 0.15 - 30));
    }
  }
}

/** The shape begins near the bottom center with small eager hops that grow taller and faster, 
 *  building irrepressible upward momentum. It then launches in a powerful surge toward the top 
 *  of the canvas, streaking upward with maximum stretch, before arcing in wide exuberant leaps 
 *  from the top-right corner to the top-left corner and back — each leap a bounding parabola 
 *  that stretches at the apex and squashes on landing. At peak euphoria the shape spirals outward 
 *  from center in expanding loops that sweep all four quadrants, spinning faster with each orbit 
 *  and shedding upward-floating spark particles. Finally it drifts into a gentle ascending float, 
 *  pulsing warmly, tracing lazy figure-eights in the upper canvas before settling near the top 
 *  center — still softly bobbing, never fully still, as if the joy lingers in every cell. */
export const ecstatic_1 = new Effervescent([
  new Phase({
    name: 'kindle',
    description: 'small bouncing hops near bottom center that grow in height and speed — barely contained anticipatory excitement building from the ground up',
    from: 0,
    to: 0.18,
    onEnter(entity, bounds) {
      const cx = (bounds.left + bounds.right) / 2;
      const bottom = bounds.bottom - 40;
      entity._effStartX = cx;
      entity._effStartY = bottom;
      entity._effBoundsL = bounds.left;
      entity._effBoundsR = bounds.right;
      entity._effBoundsT = bounds.top;
      entity._effBoundsB = bounds.bottom;
      entity._effCx = cx;
      entity._effCy = (bounds.top + bounds.bottom) / 2;
      entity.x = cx;
      entity.y = bottom;
      entity.vx = 0;
      entity.vy = 0;
      entity._effBounceTime = 0;
    },
    update(entity, dt, t) {
      const local = clamp01((t - 0) / 0.18);
      entity._effBounceTime += dt;

      const bounceFreq = 3 + local * 5;
      const bounceHeight = 30 + local * 120;
      const bouncePhase = Math.sin(entity._effBounceTime * bounceFreq * Math.PI);
      const hop = Math.max(0, bouncePhase) * bounceHeight;

      const baseY = entity._effStartY;
      entity.y = baseY - hop;
      entity.x = entity._effStartX + Math.sin(entity._effBounceTime * 2.5) * (15 + local * 25);

      const hopVel = bouncePhase > 0 ? -bounceHeight * bounceFreq * Math.PI * Math.cos(entity._effBounceTime * bounceFreq * Math.PI) : 0;
      entity.vy = hopVel * 0.3;
      entity.vx = Math.cos(entity._effBounceTime * 2.5) * (15 + local * 25) * 2.5;

      if (bouncePhase > 0.95) {
        entity.sy = 1 + 0.15 * local;
        entity.sx = 1 - 0.08 * local;
      } else if (bouncePhase < 0.05 && bouncePhase > -0.2) {
        entity.sy = 1 - 0.15 * local;
        entity.sx = 1 + 0.1 * local;
      }

      entity.radius = entity.baseRadius * (1 + local * 0.1);
    },
  }),

  new Phase({
    name: 'ascend',
    description: 'explosive upward launch from bottom to top of canvas, then sweeping parabolic leaps between top-right and top-left corners — bounding arcs at peak velocity with stretch at apex and squash at each landing',
    from: 0.18,
    to: 0.5,
    onEnter(entity) {
      entity._effAscendTime = 0;
      entity._effLeapCount = 0;
      entity._effLaunchY = entity.y;
    },
    update(entity, dt, t) {
      const local = clamp01((t - 0.18) / 0.32);
      entity._effAscendTime += dt;
      const energy = entity.energy;

      const bL = entity._effBoundsL + 40;
      const bR = entity._effBoundsR - 40;
      const bT = entity._effBoundsT + 50;
      const topY = bT + 30;

      if (local < 0.25) {
        const surge = easeOut(local / 0.25);
        entity.y = lerp(entity._effLaunchY, topY, surge);
        entity.x = lerp(entity._effCx, bR - 30, surge * 0.3);
        entity.vy = -(entity._effLaunchY - topY) * 2.5 * (1 - surge);
        entity.vx = 60;
        entity.radius = entity.baseRadius * (1 + surge * 0.25);

        if (surge > 0.5) {
          for (let i = 0; i < 2; i++) {
            entity.particles.push(new SparkParticle(entity, 0, 40));
          }
        }
      } else {
        const leapLocal = (local - 0.25) / 0.75;
        const numLeaps = 2.5;
        const leapPhase = leapLocal * numLeaps;
        const leapFrac = leapPhase % 1;
        const leapIndex = Math.floor(leapPhase);
        const goingRight = leapIndex % 2 === 0;

        const startX = goingRight ? bL : bR;
        const endX = goingRight ? bR : bL;
        const eased = easeInOut(leapFrac);

        entity.x = lerp(startX, endX, eased);

        const arcHeight = 160 + energy * 80;
        const arc = Math.sin(leapFrac * Math.PI) * arcHeight;
        entity.y = topY + 80 - arc;

        entity.vx = (endX - startX) * 1.5;
        entity.vy = -Math.cos(leapFrac * Math.PI) * arcHeight * Math.PI;

        if (leapFrac < 0.15 || leapFrac > 0.85) {
          entity.sy = 0.75;
          entity.sx = 1.25;
        } else if (leapFrac > 0.4 && leapFrac < 0.6) {
          entity.sy = 1.3;
          entity.sx = 0.8;
        }

        entity.radius = entity.baseRadius * (1 + Math.sin(leapFrac * Math.PI) * 0.2);
      }
    },
    draw(ctx, entity) {
      const energy = entity.energy;
      if (energy > 0.7) {
        ctx.globalAlpha = (energy - 0.7) * 1.5;
        ctx.beginPath();
        ctx.arc(entity.x, entity.y, entity.radius * 1.8, 0, Math.PI * 2);
        ctx.stroke();
      }
    },
  }),

  new Phase({
    name: 'exult',
    description: 'expanding spiral from center sweeping all four quadrants — the shape orbits outward with increasing radius and speed, spinning through wide loops that touch every edge of the canvas, shedding spark particles at maximum rate',
    from: 0.5,
    to: 0.78,
    onEnter(entity) {
      entity._effSpiralAngle = -Math.PI / 2;
      entity._effSpiralTime = 0;
    },
    update(entity, dt, t) {
      const local = clamp01((t - 0.5) / 0.28);
      entity._effSpiralTime += dt;
      const energy = entity.energy;

      const cx = entity._effCx;
      const cy = entity._effCy;
      const halfW = (entity._effBoundsR - entity._effBoundsL) / 2 - 30;
      const halfH = (entity._effBoundsB - entity._effBoundsT) / 2 - 30;

      const spiralExpand = easeOut(Math.min(local * 1.5, 1));
      const radiusX = 30 + spiralExpand * (halfW - 30);
      const radiusY = 30 + spiralExpand * (halfH - 30);

      const angularSpeed = 4 + energy * 6;
      entity._effSpiralAngle += angularSpeed * dt;
      const angle = entity._effSpiralAngle;

      const wobble = Math.sin(angle * 3) * 15 * energy;
      entity.x = cx + Math.cos(angle) * (radiusX + wobble);
      entity.y = cy + Math.sin(angle) * (radiusY + wobble * 0.7);

      entity.vx = -Math.sin(angle) * radiusX * angularSpeed;
      entity.vy = Math.cos(angle) * radiusY * angularSpeed;

      const pulseCycle = Math.sin(entity._effSpiralTime * 12);
      entity.radius = entity.baseRadius * (1 + 0.15 * pulseCycle + 0.15 * energy);

      entity.orientation = angle + Math.PI / 2;

      if (local > 0.7) {
        const fadeLocal = (local - 0.7) / 0.3;
        const contractFactor = 1 - easeOut(fadeLocal) * 0.6;
        entity.x = cx + (entity.x - cx) * contractFactor;
        entity.y = cy + (entity.y - cy) * contractFactor;
      }

      if (Math.random() < energy * 0.5) {
        entity.particles.push(new SparkParticle(entity, -entity.vx * 0.1, -entity.vy * 0.1 - 20));
      }
    },
    draw(ctx, entity) {
      const energy = entity.energy;
      if (energy > 0.5) {
        const alpha = (energy - 0.5) * 0.8;
        for (let i = 1; i <= 2; i++) {
          ctx.globalAlpha = alpha / (i * 1.5);
          ctx.beginPath();
          ctx.arc(entity.x, entity.y, entity.radius * (1 + i * 0.5), 0, Math.PI * 2);
          ctx.stroke();
        }
      }
    },
  }),

  new Phase({
    name: 'afterglow',
    description: 'gentle ascending figure-eight drift in the upper canvas — still pulsing warmly and bobbing with residual joy, the shape floats upward and traces lazy loops before settling near the top center, never fully still',
    from: 0.78,
    to: 1.0,
    onEnter(entity) {
      entity._effGlowTime = 0;
      entity._effGlowStartX = entity.x;
      entity._effGlowStartY = entity.y;
    },
    update(entity, dt, t) {
      const local = clamp01((t - 0.78) / 0.22);
      entity._effGlowTime += dt;
      const energy = entity.energy;

      const cx = entity._effCx;
      const topRegion = entity._effBoundsT + 80;
      const targetY = topRegion + 40;

      const settleEase = easeInOut(local);

      const figureW = (1 - local * 0.7) * 100;
      const figureH = (1 - local * 0.6) * 60;
      const figureSpeed = 2.5 - local * 1.2;
      const ft = entity._effGlowTime * figureSpeed;

      const figX = Math.sin(ft) * figureW;
      const figY = Math.sin(ft * 2) * figureH * 0.5;

      entity.x = lerp(entity._effGlowStartX, cx + figX, settleEase);
      entity.y = lerp(entity._effGlowStartY, targetY + figY, settleEase);

      entity.vx = Math.cos(ft) * figureW * figureSpeed * settleEase;
      entity.vy = Math.cos(ft * 2) * figureH * figureSpeed * settleEase;

      const gentlePulse = Math.sin(entity._effGlowTime * 5) * 0.08 * energy;
      entity.radius = entity.baseRadius * (1 + gentlePulse + 0.05 * energy);

      const bob = Math.sin(entity._effGlowTime * 3) * 0.06 * energy;
      entity.sx = 1 + bob;
      entity.sy = 1 - bob;

      entity.orientation = Math.atan2(entity.vy, entity.vx);

      if (energy > 0.3 && Math.random() < (energy - 0.2) * 0.12) {
        entity.particles.push(new SparkParticle(entity, 0, -30));
      }
    },
  }),
], {
  energyFunction: function (t) {
    if (t < 0.18) return 0.25 + 0.45 * easeOut(t / 0.18);
    if (t < 0.5) return 0.7 + 0.3 * easeOut((t - 0.18) / 0.32);
    if (t < 0.78) return 1.0 - 0.15 * ((t - 0.5) / 0.28);
    return 0.85 - 0.45 * easeOut((t - 0.78) / 0.22);
  },
});