import { Emotion } from '../../../motion-emotion-interfaces/emotion.js';
import { Phase } from '../../../motion-emotion-interfaces/phase.js';
import { Particle } from '../../../motion-emotion-interfaces/particle.js';

class FallingDrop extends Particle {
  constructor(entity) {
    super('fallingdrop', entity);
    this.x = entity.x + (Math.random() - 0.5) * entity.radius;
    this.y = entity.y + entity.radius * 0.4;
    this.vy = 25 + Math.random() * 35;
    this.vx = (Math.random() - 0.5) * 8;
    this.life = 1.0;
    this.size = 1.5 + Math.random() * 2.5;
  }

  update(dt) {
    this.x += this.vx * dt;
    this.y += this.vy * dt;
    this.vy += 55 * dt;
    this.life -= dt * 0.65;
    return this.life > 0;
  }

  draw(ctx) {
    ctx.globalAlpha = this.life * 0.35;
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.size * this.life, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1;
  }
}

class Sadness extends Emotion {
  constructor(phases, opts = {}) {
    super(phases, opts);
  }

  decorate(entity, dt) {
    const energy = entity.energy;
    entity._sadnessTime = (entity._sadnessTime || 0) + dt;

    entity.vy += 12 * energy * dt;

    entity.vx += Math.sin(entity._sadnessTime * 0.5) * 2.5 * energy * dt;

    entity.vx *= 1 - 0.25 * energy * dt;
    entity.vy *= 1 - 0.12 * energy * dt;

    entity.sy -= 0.025 * energy;
    entity.sx += 0.012 * energy;

    if (Math.random() < 0.018 * energy) {
      entity.vx += (Math.random() - 0.5) * 7;
    }

    if (Math.random() < 0.035 * energy) {
      entity.particles.push(new FallingDrop(entity));
    }
  }
}

/** The shape begins near the top center and descends under invisible weight,
 * compressing vertically and shrinking as it sinks toward the lower canvas —
 * a slow, heavy fall with slight lateral drift like a leaf with no wind.
 * At roughly 40% progress, the shape musters a feeble upward reach toward
 * center, stretching tall and narrowing as if straining against gravity;
 * the effort peaks early and collapses quickly, the shape falling back
 * heavier than before while shedding small particles that drop away beneath
 * it. In the final third the shape withdraws diagonally to the bottom-left
 * corner, radius shrinking to near-minimum, flattening into a barely-visible
 * compressed disc with fading micro-trembles and a faint shadow pooling
 * beneath it — the resigned stillness of something that tried to rise
 * and could not. */
export const wilting = new Sadness([
  new Phase({
    name: 'descend',
    description: 'Slow heavy sinking from upper center toward lower canvas, shrinking under weight with increasing vertical compression and aimless lateral drift',
    from: 0, to: 0.4,
    onEnter(entity, bounds) {
      const cx = (bounds.left + bounds.right) / 2;
      const spanY = bounds.bottom - bounds.top;
      const spanX = bounds.right - bounds.left;
      entity._sadnessStartX = cx;
      entity._sadnessStartY = bounds.top + spanY * 0.15;
      entity._sadnessLowY = bounds.top + spanY * 0.72;
      entity._sadnessCenterX = cx;
      entity._sadnessCenterY = bounds.top + spanY * 0.45;
      entity._sadnessCornerX = bounds.left + spanX * 0.18;
      entity._sadnessCornerY = bounds.top + spanY * 0.88;
      entity._sadnessTime = 0;

      entity.x = entity._sadnessStartX;
      entity.y = entity._sadnessStartY;
      entity.vx = 0;
      entity.vy = 0;
      entity.sx = 1;
      entity.sy = 1;
    },
    update(entity, dt, t) {
      const phaseT = t / 0.4;
      const eased = phaseT * phaseT;

      const targetY = entity._sadnessStartY + (entity._sadnessLowY - entity._sadnessStartY) * eased;
      const targetX = entity._sadnessStartX + Math.sin(phaseT * Math.PI * 1.2) * 35;

      const dx = targetX - entity.x;
      const dy = targetY - entity.y;
      entity.vx += dx * 1.8 * dt;
      entity.vy += dy * 1.8 * dt;

      entity.vx *= 0.96;
      entity.vy *= 0.97;

      entity.radius = entity.baseRadius * (1.0 - 0.25 * eased);

      entity.sy = 1.0 - 0.15 * eased;
      entity.sx = 1.0 + 0.08 * eased;

      entity.orientation = 0.08 * Math.sin(phaseT * Math.PI * 2.5) * (1 - phaseT * 0.7);
    },
  }),
  new Phase({
    name: 'struggle',
    description: 'A feeble attempt to rise toward center — the shape stretches upward briefly, narrows with effort, peaks early, then collapses back heavier than before while shedding particles downward',
    from: 0.4, to: 0.65,
    onEnter(entity) {
      entity._sadnessStruggleStartY = entity.y;
      entity._sadnessStruggleStartX = entity.x;
      entity._sadnessPeakY = entity._sadnessCenterY + 25;
    },
    update(entity, dt, t) {
      const phaseT = (t - 0.4) / 0.25;

      const peakPoint = 0.3;
      const riseFall = -4 * (phaseT - peakPoint) * (phaseT - peakPoint) + 4 * peakPoint * peakPoint;
      const normalizedRise = Math.max(0, riseFall);

      const baseTargetY = entity._sadnessStruggleStartY -
        (entity._sadnessStruggleStartY - entity._sadnessPeakY) * normalizedRise;

      const fallExtra = phaseT > peakPoint ? Math.pow(phaseT - peakPoint, 2) * 100 : 0;
      const finalTargetY = baseTargetY + fallExtra;

      const targetX = entity._sadnessCenterX +
        (entity._sadnessStruggleStartX - entity._sadnessCenterX) * (1 - normalizedRise * 0.6);

      const dx = targetX - entity.x;
      const dy = finalTargetY - entity.y;
      entity.vx += dx * 2.2 * dt;
      entity.vy += dy * 2.2 * dt;

      entity.vx *= 0.93;
      entity.vy *= 0.94;

      if (phaseT < peakPoint) {
        const riseT = phaseT / peakPoint;
        entity.sy = 0.85 + 0.32 * riseT;
        entity.sx = 1.08 - 0.18 * riseT;
        entity.radius = entity.baseRadius * (0.75 + 0.12 * riseT);
      } else {
        const fallT = (phaseT - peakPoint) / (1 - peakPoint);
        const easedFall = fallT * fallT;
        entity.sy = 1.17 - 0.4 * easedFall;
        entity.sx = 0.9 + 0.25 * easedFall;
        entity.radius = entity.baseRadius * (0.87 - 0.25 * easedFall);
      }

      if (phaseT > 0.35 && Math.random() < 0.14) {
        entity.particles.push(new FallingDrop(entity));
      }

      entity.orientation = 0.04 * Math.sin(phaseT * 12) * (1 - phaseT);
    },
  }),
  new Phase({
    name: 'withdraw',
    description: 'Retreats to the bottom-left corner with decelerating drift, radius shrinks to near-minimum, shape flattens into a compressed disc with fading micro-trembles and a faint shadow beneath',
    from: 0.65, to: 1.0,
    onEnter(entity) {
      entity._sadnessWithdrawStartX = entity.x;
      entity._sadnessWithdrawStartY = entity.y;
    },
    update(entity, dt, t) {
      const phaseT = (t - 0.65) / 0.35;
      const eased = 1 - (1 - phaseT) * (1 - phaseT);

      const targetX = entity._sadnessCornerX;
      const targetY = entity._sadnessCornerY;

      const currentTargetX = entity._sadnessWithdrawStartX +
        (targetX - entity._sadnessWithdrawStartX) * eased;
      const currentTargetY = entity._sadnessWithdrawStartY +
        (targetY - entity._sadnessWithdrawStartY) * eased;

      const dx = currentTargetX - entity.x;
      const dy = currentTargetY - entity.y;
      entity.vx += dx * 2.5 * dt;
      entity.vy += dy * 2.5 * dt;

      entity.vx *= 0.91;
      entity.vy *= 0.91;

      entity.radius = entity.baseRadius * (0.62 - 0.35 * eased);

      entity.sy = 0.77 - 0.12 * eased;
      entity.sx = 1.15 + 0.06 * eased;

      const trembleDecay = (1 - eased) * (1 - eased);
      entity.orientation = 0.035 * trembleDecay * Math.sin(phaseT * 28);

      if (phaseT < 0.45 && Math.random() < 0.025) {
        entity.particles.push(new FallingDrop(entity));
      }
    },
    draw(ctx, entity) {
      const alpha = 0.1 * entity.energy;
      if (alpha > 0.005) {
        ctx.globalAlpha = alpha;
        ctx.beginPath();
        ctx.ellipse(
          entity.x,
          entity.y + entity.radius + 5,
          entity.radius * 1.6,
          3,
          0, 0, Math.PI * 2
        );
        ctx.fill();
        ctx.globalAlpha = 1;
      }
    },
  }),
], {
  energyFunction: t => {
    if (t < 0.4) {
      return 0.5 - 0.15 * (t / 0.4);
    }
    if (t < 0.65) {
      const st = (t - 0.4) / 0.25;
      return 0.35 + 0.3 * Math.sin(st * Math.PI * 0.65);
    }
    const ft = (t - 0.65) / 0.35;
    return 0.22 * (1 - ft * ft);
  }
});