import { Emotion } from '../../../motion-emotion-interfaces/emotion.js';
import { Phase } from '../../../motion-emotion-interfaces/phase.js';
import { Particle } from '../../../motion-emotion-interfaces/particle.js';

class AngerEmotion extends Emotion {
  constructor(phases, opts = {}) {
    super(phases, opts);
  }

  decorate(entity, dt) {
    const e = entity.energy;

    const tremorScale = e * 3.5;
    entity.x += (Math.random() - 0.5) * tremorScale;
    entity.y += (Math.random() - 0.5) * tremorScale;

    const pulse = 1 + 0.08 * e * Math.sin(Date.now() * 0.02);
    entity.radius = entity.baseRadius * pulse;

    const speed = Math.sqrt(entity.vx * entity.vx + entity.vy * entity.vy);
    if (speed > 20) {
      entity.orientation = Math.atan2(entity.vy, entity.vx);
      const stretchAmount = Math.min(speed / 300, 0.4) * e;
      entity.sx = 1 + stretchAmount;
      entity.sy = 1 - stretchAmount * 0.5;
    }
  }
}

/** Pressure mounts as the shape retreats to center, shrinking and trembling
 * with escalating violence. At the breaking point it detonates outward in a
 * straight-line lunge toward a random wall edge, squashing flat on impact and
 * spraying spark particles, then immediately redirecting toward the farthest
 * corner. The thrash phase is sustained fury — the shape charges in aggressive
 * straight lines between corners and edge midpoints, each wall collision
 * producing sharp squash deformation and particle bursts, velocity staying
 * high as it picks the most distant target after every bounce. Finally it
 * decelerates into the nearest corner, still jolting with irregular twitches
 * that fire off sudden velocity spikes and asymmetric deformations. The
 * trembling never fully stops; energy lingers above zero — anger smolders. */
export const eruption = new AngerEmotion([
  new Phase({
    name: 'pressurize',
    description: 'Retreats to center while shrinking and trembling with increasing violence, building internal pressure before the outburst',
    from: 0, to: 0.2,
    onEnter(entity, bounds) {
      const cx = (bounds.left + bounds.right) / 2;
      const cy = (bounds.top + bounds.bottom) / 2;
      entity._angerCenter = { x: cx, y: cy };
      entity._angerBounds = bounds;
      const r = entity.baseRadius;
      const edges = [
        { x: bounds.left + r + 10, y: cy },
        { x: bounds.right - r - 10, y: cy },
        { x: cx, y: bounds.top + r + 10 },
        { x: cx, y: bounds.bottom - r - 10 },
      ];
      entity._angerTarget = edges[Math.floor(Math.random() * edges.length)];
    },
    update(entity, dt, t) {
      const phaseT = (t - 0) / 0.2;
      const center = entity._angerCenter;

      const dx = center.x - entity.x;
      const dy = center.y - entity.y;
      const pullStrength = 2.0 + phaseT * 3.0;
      entity.vx += dx * pullStrength * dt;
      entity.vy += dy * pullStrength * dt;

      entity.vx *= 0.92;
      entity.vy *= 0.92;

      entity.radius = entity.baseRadius * (1 - 0.2 * phaseT);

      const tremor = phaseT * 6;
      entity.x += (Math.random() - 0.5) * tremor;
      entity.y += (Math.random() - 0.5) * tremor;

      entity.sx = 1 - 0.1 * phaseT;
      entity.sy = 1 + 0.1 * phaseT;
    },
  }),
  new Phase({
    name: 'erupt',
    description: 'Explosive straight-line lunge toward a wall edge, impacting with violent squash deformation and spawning spark particles, then immediately rebounding toward the farthest corner',
    from: 0.2, to: 0.45,
    onEnter(entity) {
      const target = entity._angerTarget;
      const dx = target.x - entity.x;
      const dy = target.y - entity.y;
      const dist = Math.sqrt(dx * dx + dy * dy) || 1;
      const speed = 800;
      entity.vx = (dx / dist) * speed;
      entity.vy = (dy / dist) * speed;
      entity._angerBounceCount = 0;
    },
    update(entity, dt, t) {
      const bounds = entity._angerBounds;
      const r = entity.baseRadius;

      let hitWall = false;
      if (entity.x - r < bounds.left) {
        entity.x = bounds.left + r;
        entity.vx = Math.abs(entity.vx) * 0.8;
        hitWall = true;
      }
      if (entity.x + r > bounds.right) {
        entity.x = bounds.right - r;
        entity.vx = -Math.abs(entity.vx) * 0.8;
        hitWall = true;
      }
      if (entity.y - r < bounds.top) {
        entity.y = bounds.top + r;
        entity.vy = Math.abs(entity.vy) * 0.8;
        hitWall = true;
      }
      if (entity.y + r > bounds.bottom) {
        entity.y = bounds.bottom - r;
        entity.vy = -Math.abs(entity.vy) * 0.8;
        hitWall = true;
      }

      if (hitWall) {
        entity._angerBounceCount++;
        entity.sx = 1.6;
        entity.sy = 0.5;

        for (let i = 0; i < 5; i++) {
          const p = new Particle('angerSpark', entity);
          p.life = 0.3 + Math.random() * 0.2;
          p.vx = (Math.random() - 0.5) * 300;
          p.vy = (Math.random() - 0.5) * 300;
          entity.particles.push(p);
        }

        if (entity._angerBounceCount === 1) {
          const corners = [
            { x: bounds.left + r + 10, y: bounds.top + r + 10 },
            { x: bounds.right - r - 10, y: bounds.top + r + 10 },
            { x: bounds.left + r + 10, y: bounds.bottom - r - 10 },
            { x: bounds.right - r - 10, y: bounds.bottom - r - 10 },
          ];
          let best = corners[0], bestDist = 0;
          for (const c of corners) {
            const d = Math.sqrt((c.x - entity.x) ** 2 + (c.y - entity.y) ** 2);
            if (d > bestDist) { bestDist = d; best = c; }
          }
          const cdx = best.x - entity.x;
          const cdy = best.y - entity.y;
          const cdist = Math.sqrt(cdx * cdx + cdy * cdy) || 1;
          entity.vx = (cdx / cdist) * 600;
          entity.vy = (cdy / cdist) * 600;
        }
      }

      entity.sx += (1 - entity.sx) * 5 * dt;
      entity.sy += (1 - entity.sy) * 5 * dt;

      entity.radius = entity.baseRadius * (1 + 0.15 * entity.energy);
    },
  }),
  new Phase({
    name: 'thrash',
    description: 'Aggressive erratic zigzag charges between corners and edge midpoints of the canvas, sharp direction changes on every wall collision, maximum velocity and deformation, particles shed on every impact',
    from: 0.45, to: 0.78,
    onEnter(entity, bounds) {
      entity._angerThrashTimer = 0;
      const r = entity.baseRadius;
      const corners = [
        { x: bounds.left + r + 10, y: bounds.top + r + 10 },
        { x: bounds.right - r - 10, y: bounds.top + r + 10 },
        { x: bounds.left + r + 10, y: bounds.bottom - r - 10 },
        { x: bounds.right - r - 10, y: bounds.bottom - r - 10 },
      ];
      const target = corners[Math.floor(Math.random() * corners.length)];
      const dx = target.x - entity.x;
      const dy = target.y - entity.y;
      const dist = Math.sqrt(dx * dx + dy * dy) || 1;
      entity.vx = (dx / dist) * 700;
      entity.vy = (dy / dist) * 700;
    },
    update(entity, dt, t) {
      const phaseT = (t - 0.45) / 0.33;
      const bounds = entity._angerBounds;
      const r = entity.baseRadius;

      let hitWall = false;
      if (entity.x - r < bounds.left) {
        entity.x = bounds.left + r;
        entity.vx = Math.abs(entity.vx) * 0.9;
        hitWall = true;
      }
      if (entity.x + r > bounds.right) {
        entity.x = bounds.right - r;
        entity.vx = -Math.abs(entity.vx) * 0.9;
        hitWall = true;
      }
      if (entity.y - r < bounds.top) {
        entity.y = bounds.top + r;
        entity.vy = Math.abs(entity.vy) * 0.9;
        hitWall = true;
      }
      if (entity.y + r > bounds.bottom) {
        entity.y = bounds.bottom - r;
        entity.vy = -Math.abs(entity.vy) * 0.9;
        hitWall = true;
      }

      if (hitWall) {
        entity.sx = 1.6;
        entity.sy = 0.5;

        for (let i = 0; i < 4; i++) {
          const p = new Particle('angerSpark', entity);
          p.life = 0.2 + Math.random() * 0.3;
          p.vx = (Math.random() - 0.5) * 400;
          p.vy = (Math.random() - 0.5) * 400;
          entity.particles.push(p);
        }

        const targets = [
          { x: bounds.left + r + 10, y: bounds.top + r + 10 },
          { x: bounds.right - r - 10, y: bounds.top + r + 10 },
          { x: bounds.left + r + 10, y: bounds.bottom - r - 10 },
          { x: bounds.right - r - 10, y: bounds.bottom - r - 10 },
          { x: (bounds.left + bounds.right) / 2, y: bounds.top + r + 10 },
          { x: (bounds.left + bounds.right) / 2, y: bounds.bottom - r - 10 },
          { x: bounds.left + r + 10, y: (bounds.top + bounds.bottom) / 2 },
          { x: bounds.right - r - 10, y: (bounds.top + bounds.bottom) / 2 },
        ];
        let best = targets[0], bestDist = 0;
        for (const tgt of targets) {
          const d = Math.sqrt((tgt.x - entity.x) ** 2 + (tgt.y - entity.y) ** 2);
          if (d > bestDist) { bestDist = d; best = tgt; }
        }
        const dx = best.x - entity.x;
        const dy = best.y - entity.y;
        const dist = Math.sqrt(dx * dx + dy * dy) || 1;
        const speed = 500 + 300 * (1 - phaseT);
        entity.vx = (dx / dist) * speed;
        entity.vy = (dy / dist) * speed;
      }

      entity.sx += (1 - entity.sx) * 8 * dt;
      entity.sy += (1 - entity.sy) * 8 * dt;

      entity.radius = entity.baseRadius * (1.1 + 0.2 * entity.energy);

      const tremor = 4 * entity.energy;
      entity.x += (Math.random() - 0.5) * tremor;
      entity.y += (Math.random() - 0.5) * tremor;
    },
  }),
  new Phase({
    name: 'smolder',
    description: 'Decelerates into the nearest corner with residual aggressive twitches — sudden small velocity jolts and asymmetric deformations fire irregularly, trembling amplitude decreases but never reaches zero, anger lingers',
    from: 0.78, to: 1.0,
    onEnter(entity, bounds) {
      const r = entity.baseRadius;
      const corners = [
        { x: bounds.left + r + 20, y: bounds.top + r + 20 },
        { x: bounds.right - r - 20, y: bounds.top + r + 20 },
        { x: bounds.left + r + 20, y: bounds.bottom - r - 20 },
        { x: bounds.right - r - 20, y: bounds.bottom - r - 20 },
      ];
      let best = corners[0], bestDist = Infinity;
      for (const c of corners) {
        const d = Math.sqrt((c.x - entity.x) ** 2 + (c.y - entity.y) ** 2);
        if (d < bestDist) { bestDist = d; best = c; }
      }
      entity._angerCorner = best;
      entity._angerTwitchTimer = 0;
    },
    update(entity, dt, t) {
      const phaseT = (t - 0.78) / 0.22;
      const corner = entity._angerCorner;

      const dx = corner.x - entity.x;
      const dy = corner.y - entity.y;
      const pullStrength = 3.0;
      entity.vx += dx * pullStrength * dt;
      entity.vy += dy * pullStrength * dt;

      entity.vx *= 0.88;
      entity.vy *= 0.88;

      entity._angerTwitchTimer += dt;
      if (entity._angerTwitchTimer > 0.15 + Math.random() * 0.3) {
        entity._angerTwitchTimer = 0;
        const twitchStrength = 80 * (1 - phaseT * 0.7);
        entity.vx += (Math.random() - 0.5) * twitchStrength;
        entity.vy += (Math.random() - 0.5) * twitchStrength;

        entity.sx = 1 + (Math.random() - 0.5) * 0.3 * (1 - phaseT);
        entity.sy = 1 + (Math.random() - 0.5) * 0.3 * (1 - phaseT);

        if (Math.random() < 0.4) {
          const p = new Particle('angerSpark', entity);
          p.life = 0.15 + Math.random() * 0.15;
          p.vx = (Math.random() - 0.5) * 150;
          p.vy = (Math.random() - 0.5) * 150;
          entity.particles.push(p);
        }
      }

      entity.sx += (1 - entity.sx) * 3 * dt;
      entity.sy += (1 - entity.sy) * 3 * dt;

      const irregularPulse = Math.sin(t * 80) * 0.05 * (1 - phaseT);
      entity.radius = entity.baseRadius * (1 + irregularPulse);

      const tremor = 2 * (1 - phaseT * 0.8) * entity.energy;
      entity.x += (Math.random() - 0.5) * tremor;
      entity.y += (Math.random() - 0.5) * tremor;
    },
  }),
], {
  energyFunction: t => {
    if (t < 0.2) return 0.3 + 0.7 * (t / 0.2);
    if (t < 0.45) return 1.0;
    if (t < 0.78) return 0.85 + 0.15 * Math.sin(t * 20);
    return 0.4 * (1 - (t - 0.78) / 0.22) + 0.15;
  }
});