import { Emotion } from '../../../motion-emotion-interfaces/emotion.js';
import { Phase } from '../../../motion-emotion-interfaces/phase.js';
import { Particle } from '../../../motion-emotion-interfaces/particle.js';

class SurpriseEmotion extends Emotion {
  constructor(phases, opts = {}) {
    super(phases, opts);
  }

  decorate(entity, dt) {
    const energy = entity.energy;

    if (energy > 0.5) {
      const intensity = (energy - 0.5) * 2;
      const freq = 35 + intensity * 50;
      const now = performance.now() * 0.001;
      const amp = intensity * 2.5;
      entity.x += Math.sin(now * freq) * amp * dt * 60;
      entity.y += Math.cos(now * freq * 1.37) * amp * 0.6 * dt * 60;
    }

    if (entity.t > 0.32 && entity.t < 0.68) {
      const pulseT = (entity.t - 0.32) / 0.36;
      entity.radius += entity.baseRadius * 0.12 * Math.sin(pulseT * Math.PI * 8) * energy;
    }

    if (energy > 0.55 && Math.random() < (energy - 0.4) * 0.4) {
      const p = new Particle('sparkle', entity);
      const angle = Math.random() * Math.PI * 2;
      const speed = 25 + Math.random() * 90 * energy;
      p.vx = Math.cos(angle) * speed;
      p.vy = Math.sin(angle) * speed;
      p.life = 0.25 + Math.random() * 0.4;
      p.maxLife = p.life;
      entity.particles.push(p);
    }
  }
}

/** The shape drifts unsuspectingly along the lower-center in a lazy horizontal glide, 
 * then snaps into a violent upward recoil — first squashing flat against the ground 
 * for a split-second, then launching vertically toward the top of the canvas with an 
 * extreme vertical stretch and rapidly ballooning radius (the wide-eyed gasp). A burst 
 * of particles erupts from the launch point. At the apex it hangs briefly, then enters 
 * a wonder phase: darting in quick excited arcs between the upper-left and upper-right 
 * quadrants, pulsing in size, shedding sparkle particles — the delight of positive 
 * surprise. Finally it descends toward center in a series of diminishing elastic bounces, 
 * each bounce squashing on contact and stretching on ascent, until it settles near the 
 * canvas center slightly larger than its original size, still gently bobbing — an 
 * afterglow of amazement. */
export const startledBloom = new SurpriseEmotion([
  new Phase({
    name: 'unsuspecting',
    description: 'Gentle horizontal drift near the bottom-center of the canvas, small quiet radius, establishing calm baseline before the surprise event strikes',
    from: 0,
    to: 0.1,
    onEnter(entity, bounds) {
      const cx = (bounds.left + bounds.right) / 2;
      const cy = (bounds.top + bounds.bottom) / 2;
      const w = bounds.right - bounds.left;
      const h = bounds.bottom - bounds.top;
      entity._surpriseBounds = { ...bounds };
      entity._surpriseCenter = { x: cx, y: cy };
      entity._surpriseW = w;
      entity._surpriseH = h;
      entity._surpriseDriftStart = { x: cx - w * 0.12, y: bounds.top + h * 0.72 };
      entity._surpriseDriftEnd = { x: cx + w * 0.06, y: bounds.top + h * 0.70 };
      entity._surpriseLaunchTarget = { x: cx, y: bounds.top + h * 0.14 };
      entity._surpriseUpperLeft = { x: bounds.left + w * 0.2, y: bounds.top + h * 0.22 };
      entity._surpriseUpperRight = { x: bounds.right - w * 0.2, y: bounds.top + h * 0.18 };
      entity._surpriseUpperCenter = { x: cx, y: bounds.top + h * 0.25 };
      entity._surpriseBounceBase = bounds.top + h * 0.55;
      entity._surpriseSettleY = cy;
      entity.x = entity._surpriseDriftStart.x;
      entity.y = entity._surpriseDriftStart.y;
      entity.radius = entity.baseRadius * 0.82;
      entity.sx = 1.0;
      entity.sy = 1.0;
    },
    update(entity, dt, t) {
      const phaseT = t / 0.1;
      const from = entity._surpriseDriftStart;
      const to = entity._surpriseDriftEnd;
      entity.x = from.x + (to.x - from.x) * phaseT;
      entity.y = from.y + (to.y - from.y) * phaseT + Math.sin(phaseT * Math.PI) * -6;
      entity.sx = 1.0;
      entity.sy = 1.0;
      entity.radius = entity.baseRadius * 0.82;
      entity.vx = (to.x - from.x) * 0.8;
      entity.vy = -5;
      entity.orientation = Math.atan2(entity.vy, entity.vx);
    },
  }),

  new Phase({
    name: 'startle',
    description: 'Explosive upward recoil — squash flat for a split-second then launch vertically toward top with extreme vertical stretch, ballooning radius, and a particle burst from the launch point',
    from: 0.1,
    to: 0.32,
    onEnter(entity) {
      entity._surpriseLaunchX = entity.x;
      entity._surpriseLaunchY = entity.y;
      entity._surpriseBurstEmitted = false;
    },
    update(entity, dt, t) {
      const phaseT = (t - 0.1) / 0.22;
      const startX = entity._surpriseLaunchX;
      const startY = entity._surpriseLaunchY;
      const target = entity._surpriseLaunchTarget;

      if (phaseT < 0.1) {
        const squashT = phaseT / 0.1;
        const ease = squashT * squashT;
        entity.sx = 1.0 + 0.5 * ease;
        entity.sy = 1.0 - 0.35 * ease;
        entity.x = startX;
        entity.y = startY + 4 * ease;
        entity.radius = entity.baseRadius * (0.82 + 0.08 * ease);
      } else {
        if (!entity._surpriseBurstEmitted) {
          entity._surpriseBurstEmitted = true;
          for (let i = 0; i < 16; i++) {
            const p = new Particle('burst', entity);
            const angle = (Math.PI * 2 * i) / 16 + Math.random() * 0.2;
            const speed = 100 + Math.random() * 150;
            p.vx = Math.cos(angle) * speed;
            p.vy = Math.sin(angle) * speed;
            p.life = 0.4 + Math.random() * 0.3;
            p.maxLife = p.life;
            entity.particles.push(p);
          }
        }

        const launchT = (phaseT - 0.1) / 0.9;
        const easeOut = 1 - Math.pow(1 - launchT, 3);

        entity.x = startX + (target.x - startX) * easeOut;
        entity.y = startY + (target.y - startY) * easeOut;

        const stretchCurve = Math.sin(launchT * Math.PI);
        entity.sy = 1.0 + stretchCurve * 0.6;
        entity.sx = 1.0 - stretchCurve * 0.25;

        entity.radius = entity.baseRadius * (0.9 + 0.55 * easeOut);

        entity.vy = (target.y - startY) * 3 * Math.pow(1 - launchT, 2);
        entity.vx = (target.x - startX) * 0.5;
        entity.orientation = Math.atan2(entity.vy, entity.vx);
      }
    },
    draw(ctx, entity) {
      if (entity._surpriseBurstEmitted && entity.t < 0.22) {
        const age = (entity.t - 0.1) / 0.12;
        if (age > 0 && age < 1) {
          const ringRadius = entity.baseRadius * 0.5 + age * entity._surpriseH * 0.15;
          const alpha = (1 - age) * 0.4;
          ctx.beginPath();
          ctx.arc(entity._surpriseLaunchX, entity._surpriseLaunchY, ringRadius, 0, Math.PI * 2);
          ctx.strokeStyle = `rgba(255,255,255,${alpha})`;
          ctx.lineWidth = 2.5 * (1 - age);
          ctx.stroke();
        }
      }
    },
  }),

  new Phase({
    name: 'wonder',
    description: 'Floats in the upper canvas darting in excited arcs between upper-left and upper-right quadrants, pulsing in size with sparkle particles — the delighted astonishment of positive surprise',
    from: 0.32,
    to: 0.68,
    onEnter(entity) {
      entity._surpriseWonderStartX = entity.x;
      entity._surpriseWonderStartY = entity.y;
    },
    update(entity, dt, t) {
      const phaseT = (t - 0.32) / 0.36;
      const ul = entity._surpriseUpperLeft;
      const ur = entity._surpriseUpperRight;
      const uc = entity._surpriseUpperCenter;

      let targetX, targetY;

      if (phaseT < 0.3) {
        const segT = phaseT / 0.3;
        const ease = 1 - Math.pow(1 - segT, 2.5);
        const fromX = entity._surpriseWonderStartX;
        const fromY = entity._surpriseWonderStartY;
        targetX = fromX + (ul.x - fromX) * ease;
        targetY = fromY + (ul.y - fromY) * ease;
        targetY += Math.sin(segT * Math.PI) * -entity._surpriseH * 0.06;
      } else if (phaseT < 0.6) {
        const segT = (phaseT - 0.3) / 0.3;
        const ease = segT < 0.5
          ? 2 * segT * segT
          : 1 - Math.pow(-2 * segT + 2, 2) / 2;
        targetX = ul.x + (ur.x - ul.x) * ease;
        targetY = ul.y + (ur.y - ul.y) * ease;
        targetY += Math.sin(segT * Math.PI) * -entity._surpriseH * 0.08;
      } else {
        const segT = (phaseT - 0.6) / 0.4;
        const ease = 1 - Math.pow(1 - segT, 2);
        targetX = ur.x + (uc.x - ur.x) * ease;
        targetY = ur.y + (uc.y - ur.y) * ease;
        targetY += Math.sin(segT * Math.PI) * -entity._surpriseH * 0.04;
      }

      const prevX = entity.x;
      const prevY = entity.y;
      entity.x = targetX;
      entity.y = targetY;
      entity.vx = (entity.x - prevX) / Math.max(dt, 0.001);
      entity.vy = (entity.y - prevY) / Math.max(dt, 0.001);
      entity.orientation = Math.atan2(entity.vy, entity.vx);

      const speed = Math.sqrt(entity.vx * entity.vx + entity.vy * entity.vy);
      const normSpeed = Math.min(speed / 400, 1);
      entity.sx = 1.0 + normSpeed * 0.2;
      entity.sy = 1.0 - normSpeed * 0.1;

      entity.radius = entity.baseRadius * (1.2 + 0.1 * Math.sin(phaseT * Math.PI * 5));
    },
    draw(ctx, entity) {
      if (entity.t >= 0.32 && entity.t <= 0.68) {
        const phaseT = (entity.t - 0.32) / 0.36;
        const alpha = 0.15 * entity.energy * Math.sin(phaseT * Math.PI);
        if (alpha > 0.01) {
          const glowRadius = entity.radius * 2.2;
          const grad = ctx.createRadialGradient(
            entity.x, entity.y, entity.radius * 0.5,
            entity.x, entity.y, glowRadius
          );
          grad.addColorStop(0, `rgba(255,255,255,${alpha})`);
          grad.addColorStop(1, 'rgba(255,255,255,0)');
          ctx.beginPath();
          ctx.arc(entity.x, entity.y, glowRadius, 0, Math.PI * 2);
          ctx.fillStyle = grad;
          ctx.fill();
        }
      }
    },
  }),

  new Phase({
    name: 'settle',
    description: 'Descends toward canvas center in a series of diminishing elastic bounces — each bounce squashes on contact and stretches on ascent — settling slightly larger than original with a gentle residual bob',
    from: 0.68,
    to: 1.0,
    onEnter(entity) {
      entity._surpriseSettleStartX = entity.x;
      entity._surpriseSettleStartY = entity.y;
    },
    update(entity, dt, t) {
      const phaseT = (t - 0.68) / 0.32;
      const startX = entity._surpriseSettleStartX;
      const startY = entity._surpriseSettleStartY;
      const endX = entity._surpriseCenter.x;
      const endY = entity._surpriseSettleY;

      const xEase = 1 - Math.pow(1 - phaseT, 2);
      entity.x = startX + (endX - startX) * xEase;

      const baseY = startY + (endY - startY) * xEase;

      const bounceCount = 4;
      const bounceDecay = 0.55;
      const bounceFreq = bounceCount * Math.PI;
      const bounceAmp = entity._surpriseH * 0.12;
      const dampedBounce = Math.abs(Math.sin(phaseT * bounceFreq))
        * bounceAmp * Math.pow(1 - phaseT, 2.2);

      entity.y = baseY - dampedBounce;

      const bouncePhase = Math.sin(phaseT * bounceFreq);
      const bounceMag = Math.abs(bouncePhase) * Math.pow(1 - phaseT, 2.2);

      if (bouncePhase < -0.2 && bounceMag > 0.05) {
        const squash = bounceMag * 0.4;
        entity.sx = 1.0 + squash;
        entity.sy = 1.0 - squash * 0.7;
      } else if (bouncePhase > 0.2 && bounceMag > 0.05) {
        const stretch = bounceMag * 0.25;
        entity.sx = 1.0 - stretch * 0.5;
        entity.sy = 1.0 + stretch;
      } else {
        const returnRate = 0.15;
        entity.sx = entity.sx + (1.0 - entity.sx) * returnRate;
        entity.sy = entity.sy + (1.0 - entity.sy) * returnRate;
      }

      entity.radius = entity.baseRadius * (1.2 - 0.12 * phaseT);

      const prevX = entity.x;
      entity.vx = (endX - startX) * 0.3 * (1 - phaseT);
      entity.vy = -dampedBounce * 3 * Math.cos(phaseT * bounceFreq);
      entity.orientation = Math.atan2(entity.vy, entity.vx);

      if (phaseT > 0.85) {
        const bobT = (phaseT - 0.85) / 0.15;
        entity.y += Math.sin(bobT * Math.PI * 3) * 2 * (1 - bobT);
      }
    },
  }),
], {
  energyFunction: function (t) {
    if (t < 0.1) return 0.2 + 0.15 * (t / 0.1);
    if (t < 0.32) {
      const rampT = (t - 0.1) / 0.22;
      return 0.35 + 0.65 * (1 - Math.pow(1 - rampT, 2));
    }
    if (t < 0.68) {
      const wonderT = (t - 0.32) / 0.36;
      return 0.85 - 0.15 * wonderT;
    }
    const settleT = (t - 0.68) / 0.32;
    return 0.7 - 0.35 * settleT;
  },
});