import { Emotion } from '../../../motion-emotion-interfaces/emotion.js';
import { Phase } from '../../../motion-emotion-interfaces/phase.js';

function seekTarget(entity, tx, ty, strength, dt) {
  const dx = tx - entity.x;
  const dy = ty - entity.y;
  const dist = Math.sqrt(dx * dx + dy * dy) || 1;
  entity.vx += (dx / dist) * strength * dt;
  entity.vy += (dy / dist) * strength * dt;
}

function lerp(a, b, t) {
  return a + (b - a) * t;
}

function easeInOut(t) {
  return t < 0.5 ? 2 * t * t : 1 - 2 * (1 - t) * (1 - t);
}

class Languishing extends Emotion {
  constructor(phases, opts = {}) {
    super(phases, opts);
  }

  decorate(entity, dt) {
    const energy = entity.energy;

    if (entity._langSighT === undefined) entity._langSighT = 0;
    entity._langSighT += dt;

    const sighWave = Math.sin(entity._langSighT * 1.1);
    const sighScale = 1.0 + 0.04 * sighWave * (1.0 - energy * 0.5);
    entity.radius = entity.baseRadius * sighScale;

    entity.sy = 1.0 + 0.14 * (1.0 - energy);
    entity.sx = 1.0 - 0.07 * (1.0 - energy);

    const heaviness = 1.0 - energy;
    entity.vy += 6 * heaviness * dt;

    const dampFactor = 0.88 - 0.08 * heaviness;
    const frameDamp = Math.pow(dampFactor, 60 * dt);
    entity.vx *= frameDamp;
    entity.vy *= frameDamp;

    entity.orientation += Math.sin(entity._langSighT * 0.7) * 0.002 * heaviness;
  }
}

/** The shape sinks sluggishly from its starting position toward the lower-left
 *  quadrant, sagging under its own weight in a slow gravitational slouch. It then
 *  meanders in a wide, lazy S-curve across the full width of the canvas — left edge
 *  to right edge — staying in the lower half, never accelerating, as though dragged
 *  through thick air with no destination in mind. Near the 60% mark a flicker of
 *  restlessness lifts it: the shape rises toward the upper-right corner in a brief
 *  half-hearted lunge, but the impulse dies almost immediately and it curves back
 *  downward without reaching its target. Finally it resigns, sinking to the bottom
 *  center of the canvas where it flattens into a heavy squash, swaying side to side
 *  in a tiny pendulum arc that decays to near-total stillness. Throughout, periodic
 *  slow radius pulses read as sighs, and persistent vertical stretch conveys weight. */
export const languishing = new Languishing([
  new Phase({
    name: 'sink',
    description: 'shape drifts downward from start position toward lower-left of center, decelerating into a slouch — gravitational sag increasing throughout',
    from: 0,
    to: 0.2,
    onEnter(entity, bounds) {
      const cx = (bounds.left + bounds.right) / 2;
      const cy = (bounds.top + bounds.bottom) / 2;
      const w = bounds.right - bounds.left;
      const h = bounds.bottom - bounds.top;
      entity._langBounds = bounds;
      entity._langW = w;
      entity._langH = h;
      entity._langCx = cx;
      entity._langCy = cy;
      entity._langSighT = 0;
      entity._langSinkTarget = {
        x: cx - w * 0.2,
        y: cy + h * 0.18
      };
      entity._langStartX = entity.x;
      entity._langStartY = entity.y;
    },
    update(entity, dt, t) {
      const phaseT = Math.min(1, (t - 0) / 0.2);
      const ease = easeInOut(phaseT);
      const target = entity._langSinkTarget;
      const goalX = lerp(entity._langStartX, target.x, ease);
      const goalY = lerp(entity._langStartY, target.y, ease);
      seekTarget(entity, goalX, goalY, 60, dt);
    }
  }),

  new Phase({
    name: 'meander',
    description: 'lazy S-curve drift across the full canvas width through the lower half — aimless wandering with no urgency, covering left edge to right edge in a shallow sinusoidal path',
    from: 0.2,
    to: 0.55,
    onEnter(entity, bounds) {
      const w = entity._langW;
      const h = entity._langH;
      entity._langMeanderStart = { x: entity.x, y: entity.y };
      entity._langWaypoints = [
        { x: bounds.left + w * 0.12, y: bounds.top + h * 0.6 },
        { x: bounds.left + w * 0.35, y: bounds.top + h * 0.72 },
        { x: bounds.left + w * 0.6,  y: bounds.top + h * 0.55 },
        { x: bounds.right - w * 0.1, y: bounds.top + h * 0.65 }
      ];
    },
    update(entity, dt, t) {
      const phaseT = (t - 0.2) / 0.35;
      const waypoints = entity._langWaypoints;
      const totalSegments = waypoints.length;
      const rawIdx = phaseT * totalSegments;
      const segIdx = Math.min(Math.floor(rawIdx), totalSegments - 1);
      const segT = rawIdx - segIdx;
      const ease = easeInOut(Math.min(1, segT));

      const prevPt = segIdx === 0 ? entity._langMeanderStart : waypoints[segIdx - 1];
      const currPt = waypoints[segIdx];
      const goalX = lerp(prevPt.x, currPt.x, ease);
      const goalY = lerp(prevPt.y, currPt.y, ease);

      seekTarget(entity, goalX, goalY, 45, dt);

      const wobble = Math.sin(phaseT * Math.PI * 5) * 4 * entity.energy;
      entity.vx += wobble * dt;
    }
  }),

  new Phase({
    name: 'stir',
    description: 'brief restless surge — shape lifts toward upper-right corner as if something caught its attention, but the impulse dies halfway and it curves back down, the half-hearted lunge collapsing under its own disinterest',
    from: 0.55,
    to: 0.72,
    onEnter(entity, bounds) {
      const w = entity._langW;
      const h = entity._langH;
      entity._langStirStart = { x: entity.x, y: entity.y };
      entity._langStirPeak = {
        x: bounds.right - w * 0.18,
        y: bounds.top + h * 0.22
      };
      entity._langStirFallback = {
        x: bounds.left + w * 0.55,
        y: bounds.top + h * 0.6
      };
    },
    update(entity, dt, t) {
      const phaseT = (t - 0.55) / 0.17;
      let goalX, goalY;

      if (phaseT < 0.45) {
        const riseT = easeInOut(phaseT / 0.45);
        goalX = lerp(entity._langStirStart.x, entity._langStirPeak.x, riseT * 0.55);
        goalY = lerp(entity._langStirStart.y, entity._langStirPeak.y, riseT * 0.55);
        seekTarget(entity, goalX, goalY, 90, dt);
      } else {
        const fallT = easeInOut((phaseT - 0.45) / 0.55);
        const midX = lerp(entity._langStirStart.x, entity._langStirPeak.x, 0.55);
        const midY = lerp(entity._langStirStart.y, entity._langStirPeak.y, 0.55);
        goalX = lerp(midX, entity._langStirFallback.x, fallT);
        goalY = lerp(midY, entity._langStirFallback.y, fallT);
        seekTarget(entity, goalX, goalY, 55, dt);
      }

      if (phaseT < 0.3) {
        const trembleAmt = 12 * entity.energy;
        entity.vx += (Math.random() - 0.5) * trembleAmt * dt * 60;
        entity.vy += (Math.random() - 0.5) * trembleAmt * dt * 60;
      }
    }
  }),

  new Phase({
    name: 'resign',
    description: 'shape sinks to bottom-center of canvas, flattening into heavy squash with a gentle pendulum sway that decays to near-complete stillness — total surrender to unstimulation',
    from: 0.72,
    to: 1.0,
    onEnter(entity, bounds) {
      const w = entity._langW;
      const h = entity._langH;
      entity._langResignTarget = {
        x: (bounds.left + bounds.right) / 2,
        y: bounds.bottom - h * 0.12
      };
      entity._langResignStart = { x: entity.x, y: entity.y };
      entity._langSwayPhase = 0;
    },
    update(entity, dt, t) {
      const phaseT = (t - 0.72) / 0.28;
      const ease = easeInOut(Math.min(1, phaseT * 1.3));
      const target = entity._langResignTarget;

      const goalX = lerp(entity._langResignStart.x, target.x, ease);
      const goalY = lerp(entity._langResignStart.y, target.y, ease);

      seekTarget(entity, goalX, goalY, 50, dt);

      entity._langSwayPhase += dt;
      const swayDecay = Math.max(0, 1.0 - phaseT);
      const swayAmp = 25 * swayDecay * swayDecay;
      entity.vx += Math.sin(entity._langSwayPhase * 1.4) * swayAmp * dt;

      entity.sy = 1.0 + 0.18 * ease;
      entity.sx = 1.0 - 0.09 * ease;

      entity.radius = entity.baseRadius * (1.0 - 0.06 * ease);
    },
    draw(ctx, entity) {
      const phaseT = (entity.t - 0.72) / 0.28;
      if (phaseT > 0.6) {
        const alpha = 0.08 * (1.0 - phaseT);
        ctx.save();
        ctx.globalAlpha = alpha;
        ctx.beginPath();
        ctx.ellipse(
          entity.x, entity.y + entity.radius * 1.2,
          entity.radius * 1.5, entity.radius * 0.2,
          0, 0, Math.PI * 2
        );
        ctx.fillStyle = 'currentColor';
        ctx.fill();
        ctx.restore();
      }
    }
  })
], {
  energyFunction: function (t) {
    if (t < 0.2) return 0.28 - 0.08 * (t / 0.2);
    if (t < 0.55) return 0.2 + 0.1 * Math.sin(((t - 0.2) / 0.35) * Math.PI);
    if (t < 0.72) {
      const stirT = (t - 0.55) / 0.17;
      return 0.2 + 0.35 * Math.sin(stirT * Math.PI);
    }
    return 0.18 * (1.0 - ((t - 0.72) / 0.28));
  }
});