import { Emotion } from '../../../motion-emotion-interfaces/emotion.js';
import { Phase } from '../../../motion-emotion-interfaces/phase.js';
import { Particle } from '../../../motion-emotion-interfaces/particle.js';

class Awe extends Emotion {
  constructor(phases, opts = {}) {
    super(phases, opts);
  }

  decorate(entity, dt) {
    const energy = entity.energy;

    if (!entity._aweAccum) entity._aweAccum = 0;
    entity._aweAccum += dt;

    const breathAmp = 0.025 + energy * 0.055;
    const breath = Math.sin(entity._aweAccum * 2.8) * breathAmp;
    entity.sx += breath;
    entity.sy += breath * 0.6;

    if (energy > 0.3 && Math.random() < energy * 0.22) {
      const angle = Math.random() * Math.PI * 2;
      const dist = entity.radius * (1.0 + Math.random() * 3.0);
      const p = new Particle('awe_mote', entity);
      p.x = entity.x + Math.cos(angle) * dist;
      p.y = entity.y + Math.sin(angle) * dist;
      p.vx = Math.cos(angle) * 12 * energy;
      p.vy = Math.sin(angle) * 12 * energy - 20 * energy;
      p.life = 0.7 + Math.random() * 1.2;
      p.maxLife = p.life;
      p.size = 1.5 + Math.random() * 3.5 * energy;
      entity.particles.push(p);
    }

    if (energy > 0.7 && Math.random() < (energy - 0.7) * 0.6) {
      const p = new Particle('awe_ring', entity);
      p.x = entity.x;
      p.y = entity.y;
      p.vx = 0;
      p.vy = 0;
      p.life = 1.2;
      p.maxLife = 1.2;
      p.size = entity.radius * 0.5;
      p.growRate = 80;
      entity.particles.push(p);
    }
  }
}

/** The shape begins near bottom-center at reduced size, as if struck still by an encounter
 * with vastness. It briefly contracts and trembles — a held breath. Then it begins a slow,
 * reverent ascent toward the upper canvas, stretching vertically as if drawn upward by an
 * unseen force, radius gradually swelling. Near the top, it enters full overwhelm: the shape
 * expands to maximum size and traces a slow, wide arc across the upper third of the canvas,
 * radiating mote-like particles outward and pulsing with deep breath-rhythm. Faint expanding
 * rings emanate from the shape at peak wonder. Finally it begins a dreamy, swaying descent
 * back toward center — still enlarged, still gently pulsing — drifting side to side like a
 * leaf in still air, settling into quiet, transformed stillness with lingering sparkle particles. */
export const celestialGaze = new Awe([
  new Phase({
    name: 'encounter',
    description: 'Shape drifts to bottom-center and shrinks, a held-breath moment of first contact with vastness — slight tremble, radius contracts below base',
    from: 0,
    to: 0.15,
    onEnter(entity, bounds) {
      const cx = (bounds.left + bounds.right) / 2;
      const cy = (bounds.top + bounds.bottom) / 2;
      const height = bounds.bottom - bounds.top;
      const width = bounds.right - bounds.left;

      entity._aweBounds = { ...bounds };
      entity._aweCenter = { x: cx, y: cy };
      entity._aweBottom = { x: cx, y: bounds.bottom - height * 0.18 };
      entity._aweTop = { x: cx, y: bounds.top + height * 0.18 };
      entity._aweWidth = width;
      entity._aweHeight = height;
      entity._aweStartX = entity.x;
      entity._aweStartY = entity.y;
      entity._aweAccum = 0;
      entity._aweMinRadius = entity.baseRadius * 0.55;
      entity._aweMaxRadius = entity.baseRadius * 1.8;
      entity._aweArcAngle = 0;
    },
    update(entity, dt, t) {
      const phaseT = Math.min(1, (t - 0) / 0.15);
      const ease = phaseT * phaseT;

      const target = entity._aweBottom;
      entity.x += (target.x - entity.x) * 2.5 * dt;
      entity.y += (target.y - entity.y) * 2.5 * dt;

      entity.radius = entity.baseRadius + (entity._aweMinRadius - entity.baseRadius) * ease;

      const tremble = Math.sin(phaseT * Math.PI * 18) * 1.5 * ease;
      entity.x += tremble;

      entity.vx *= 0.9;
      entity.vy *= 0.9;

      entity.sx = 1.0 - 0.04 * ease;
      entity.sy = 1.0 - 0.06 * ease;

      entity.orientation = Math.sin(phaseT * Math.PI * 8) * 0.05 * ease;
    },
  }),
  new Phase({
    name: 'ascend',
    description: 'Slow reverent rise from bottom toward upper canvas, shape elongates vertically as if drawn upward, radius gradually swelling back and beyond base size',
    from: 0.15,
    to: 0.50,
    onEnter(entity) {
      entity._aweAscendStartY = entity.y;
      entity._aweAscendStartX = entity.x;
    },
    update(entity, dt, t) {
      const phaseT = Math.min(1, (t - 0.15) / 0.35);
      const easeUp = 1 - Math.pow(1 - phaseT, 2.5);

      const targetY = entity._aweTop.y;
      const startY = entity._aweAscendStartY || entity._aweBottom.y;
      const goalY = startY + (targetY - startY) * easeUp;

      const gentleSway = Math.sin(phaseT * Math.PI * 3) * entity._aweWidth * 0.06;
      const goalX = entity._aweCenter.x + gentleSway;

      entity.vx += (goalX - entity.x) * 3.0 * dt;
      entity.vy += (goalY - entity.y) * 3.0 * dt;

      entity.vx *= 0.92;
      entity.vy *= 0.92;

      entity.x += entity.vx * dt;
      entity.y += entity.vy * dt;

      const radiusTarget = entity._aweMinRadius + (entity._aweMaxRadius - entity._aweMinRadius) * easeUp;
      entity.radius += (radiusTarget - entity.radius) * 3 * dt;

      entity.sy = 1.0 + 0.18 * easeUp;
      entity.sx = 1.0 - 0.06 * easeUp;

      entity.orientation = Math.sin(phaseT * Math.PI * 2) * 0.03;

      entity.energy = Math.min(1, entity.energy);
    },
  }),
  new Phase({
    name: 'overwhelm',
    description: 'At the top of the canvas, shape swells to maximum size and traces a slow wide arc across upper third, radiating particles and expanding rings at peak wonder',
    from: 0.50,
    to: 0.75,
    onEnter(entity) {
      entity._aweArcAngle = Math.atan2(
        entity.y - entity._aweTop.y,
        entity.x - entity._aweTop.x
      );
    },
    update(entity, dt, t) {
      const phaseT = Math.min(1, (t - 0.50) / 0.25);

      entity._aweArcAngle += dt * 0.7;
      const arcRadius = entity._aweWidth * 0.3;
      const arcCenterY = entity._aweBounds.top + entity._aweHeight * 0.25;

      const goalX = entity._aweCenter.x + Math.cos(entity._aweArcAngle - Math.PI / 2) * arcRadius;
      const goalY = arcCenterY + Math.sin(entity._aweArcAngle - Math.PI / 2) * arcRadius * 0.35;

      entity.vx += (goalX - entity.x) * 2.5 * dt;
      entity.vy += (goalY - entity.y) * 2.5 * dt;

      entity.vx *= 0.93;
      entity.vy *= 0.93;

      entity.x += entity.vx * dt;
      entity.y += entity.vy * dt;

      const swell = 1.0 + 0.08 * Math.sin(phaseT * Math.PI * 4);
      entity.radius += (entity._aweMaxRadius * swell - entity.radius) * 4 * dt;

      const breathCycle = Math.sin(phaseT * Math.PI * 6);
      entity.sx = 1.0 + 0.08 * breathCycle;
      entity.sy = 1.0 + 0.1 * breathCycle;

      entity.orientation += dt * 0.3;
    },
    draw(ctx, entity) {
      const energy = entity.energy;
      if (energy < 0.6) return;
      const alpha = (energy - 0.6) * 0.3;
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 1;
      for (let i = 0; i < 3; i++) {
        const r = entity.radius * (1.3 + i * 0.5) + Math.sin(entity._aweAccum * 2 + i) * 5;
        ctx.beginPath();
        ctx.arc(entity.x, entity.y, r, 0, Math.PI * 2);
        ctx.stroke();
      }
      ctx.restore();
    },
  }),
  new Phase({
    name: 'settle',
    description: 'Dreamy swaying descent back toward center, still enlarged and gently pulsing, drifting side to side like a leaf in still air, resolving into quiet transformed stillness',
    from: 0.75,
    to: 1.0,
    update(entity, dt, t) {
      const phaseT = Math.min(1, (t - 0.75) / 0.25);
      const easeDown = phaseT * phaseT * (3 - 2 * phaseT);

      const goalY = entity._aweTop.y + (entity._aweCenter.y - entity._aweTop.y) * easeDown;
      const swayAmp = entity._aweWidth * 0.12 * (1 - phaseT * 0.7);
      const goalX = entity._aweCenter.x + Math.sin(phaseT * Math.PI * 4) * swayAmp;

      entity.vx += (goalX - entity.x) * 2.0 * dt;
      entity.vy += (goalY - entity.y) * 2.0 * dt;

      entity.vx *= 0.90;
      entity.vy *= 0.90;

      entity.x += entity.vx * dt;
      entity.y += entity.vy * dt;

      const targetRadius = entity._aweMaxRadius + (entity.baseRadius * 1.15 - entity._aweMaxRadius) * easeDown;
      entity.radius += (targetRadius - entity.radius) * 3 * dt;

      const gentleBreath = Math.sin(phaseT * Math.PI * 5) * 0.04 * (1 - phaseT);
      entity.sx = 1.0 + gentleBreath;
      entity.sy = 1.0 + gentleBreath * 0.8;

      entity.orientation *= 0.97;

      entity.vx *= (1 - easeDown * 0.3);
      entity.vy *= (1 - easeDown * 0.3);
    },
  }),
], {
  energyFunction: t => {
    if (t < 0.15) return 0.2 + 0.3 * (t / 0.15);
    if (t < 0.50) return 0.5 + 0.5 * ((t - 0.15) / 0.35);
    if (t < 0.75) return 1.0;
    return 1.0 - 0.35 * ((t - 0.75) / 0.25);
  },
});