import { Emotion } from '../../../motion-emotion-interfaces/emotion.js';
import { Phase } from '../../../motion-emotion-interfaces/phase.js';

class Confusion extends Emotion {
  constructor(phases, opts = {}) {
    super(phases, opts);
  }

  decorate(entity, dt) {
    const energy = entity.energy;
    const time = Date.now() / 1000;
    const seed = entity._confusionSeed || 0;

    const trembleAmt = 1 + energy * 4;
    entity.x += Math.sin(time * 13.7 + seed) * trembleAmt * dt * 10;
    entity.y += Math.cos(time * 11.3 + seed * 1.3) * trembleAmt * dt * 10;

    entity.orientation += Math.sin(time * 5.1 + seed) * energy * 2 * dt;

    const pulse = Math.sin(time * 7.2 + seed);
    entity.sx += pulse * 0.05 * energy;
    entity.sy -= pulse * 0.03 * energy;
  }
}

/** The shape starts near center and lurches toward one corner, then abruptly
 * redirects toward a different corner before arriving — cycling between all
 * four corners with accelerating indecision, never completing a single journey.
 * It then falls into an erratic orbit around the center, the radius expanding
 * and contracting irregularly while angular speed lurches between fast and slow,
 * as if caught in a feedback loop of second-guessing. Next the shape scatters —
 * darting rapidly toward edges (top, right, bottom, left) but reversing course
 * every quarter-second, zigzagging across the full canvas in panicked bursts,
 * stretching in the direction of each aborted dash. Finally it drifts sluggishly
 * back toward center, making small impulsive lunges in random directions that
 * grow weaker and less frequent, wobbling and trembling as it subsides into
 * defeated, disoriented stillness. Throughout all phases a persistent positional
 * tremble and orientation jitter layer on top, reinforcing unsteadiness. */
export const bewildered = new Confusion([
  new Phase({
    name: 'seeking',
    description: 'Shape heads toward one corner then abruptly redirects toward another, cycling through all four with increasing urgency — indecisive, unable to commit to a direction',
    from: 0, to: 0.3,
    onEnter(entity, bounds) {
      entity._confusionSeed = Math.random() * 100;
      const cx = (bounds.left + bounds.right) / 2;
      const cy = (bounds.top + bounds.bottom) / 2;
      entity._confCenter = { x: cx, y: cy };

      const margin = 55;
      entity._confCorners = [
        { x: bounds.left + margin, y: bounds.top + margin },
        { x: bounds.right - margin, y: bounds.top + margin },
        { x: bounds.right - margin, y: bounds.bottom - margin },
        { x: bounds.left + margin, y: bounds.bottom - margin },
      ];
      entity._confTargetIdx = Math.floor(Math.random() * 4);
      entity._confSwitchTimer = 0;

      entity.x = cx;
      entity.y = cy;
      entity.vx = 0;
      entity.vy = 0;
    },
    update(entity, dt, t) {
      const phaseT = Math.min(1, (t - 0) / 0.3);
      entity._confSwitchTimer += dt;

      const interval = 0.55 - phaseT * 0.32;
      if (entity._confSwitchTimer > interval) {
        entity._confSwitchTimer = 0;
        let newIdx;
        do {
          newIdx = Math.floor(Math.random() * entity._confCorners.length);
        } while (newIdx === entity._confTargetIdx);
        entity._confTargetIdx = newIdx;
      }

      const target = entity._confCorners[entity._confTargetIdx];
      const dx = target.x - entity.x;
      const dy = target.y - entity.y;
      const dist = Math.sqrt(dx * dx + dy * dy) || 1;

      const accel = (220 + phaseT * 180) * entity.energy;
      entity.vx += (dx / dist) * accel * dt * 4;
      entity.vy += (dy / dist) * accel * dt * 4;

      entity.vx *= 0.91;
      entity.vy *= 0.91;

      entity.x += entity.vx * dt;
      entity.y += entity.vy * dt;

      const spd = Math.sqrt(entity.vx * entity.vx + entity.vy * entity.vy);
      const stretchAmt = Math.min(spd / 350, 0.22) * entity.energy;
      entity.orientation = Math.atan2(entity.vy, entity.vx);
      entity.sx = 1.0 + stretchAmt;
      entity.sy = 1.0 - stretchAmt * 0.5;

      entity.radius = entity.baseRadius * (1.0 + Math.sin(phaseT * Math.PI * 6) * 0.12 * entity.energy);
    },
  }),
  new Phase({
    name: 'spiraling',
    description: 'Irregular orbit around center with erratic radius and speed changes — caught in a loop of indecision, unable to break free or settle',
    from: 0.3, to: 0.55,
    onEnter(entity, bounds) {
      const center = entity._confCenter;
      entity._confSpiralAngle = Math.atan2(entity.y - center.y, entity.x - center.x);
      entity._confSpiralRadius = Math.sqrt(
        (entity.x - center.x) ** 2 + (entity.y - center.y) ** 2
      ) || 80;
    },
    update(entity, dt, t) {
      const phaseT = Math.min(1, (t - 0.3) / 0.25);
      const center = entity._confCenter;
      const seed = entity._confusionSeed;

      const angularSpeed = 2.8 + Math.sin(phaseT * Math.PI * 7.3 + seed) * 1.8
                               + Math.sin(phaseT * Math.PI * 3.1 + seed * 0.7) * 1.2;
      entity._confSpiralAngle += angularSpeed * dt;

      const baseR = 130;
      const radiusOsc = Math.sin(phaseT * Math.PI * 5.1 + seed) * 65
                      + Math.sin(phaseT * Math.PI * 8.7 + seed * 1.5) * 35;
      const targetR = baseR + radiusOsc;
      entity._confSpiralRadius += (targetR - entity._confSpiralRadius) * dt * 5;

      const targetX = center.x + Math.cos(entity._confSpiralAngle) * entity._confSpiralRadius;
      const targetY = center.y + Math.sin(entity._confSpiralAngle) * entity._confSpiralRadius;

      entity.vx = (targetX - entity.x) * 7;
      entity.vy = (targetY - entity.y) * 7;

      entity.x += entity.vx * dt;
      entity.y += entity.vy * dt;

      entity.orientation = entity._confSpiralAngle + Math.sin(phaseT * Math.PI * 11 + seed) * 0.6;

      const stretch = Math.sin(phaseT * Math.PI * 9 + seed) * 0.18 * entity.energy;
      entity.sx = 1.0 + stretch;
      entity.sy = 1.0 - stretch * 0.65;

      entity.radius = entity.baseRadius * (1.0 + Math.sin(phaseT * Math.PI * 4.5) * 0.1);
    },
  }),
  new Phase({
    name: 'scattering',
    description: 'Rapid panicked darts toward edges, reversing before arriving, zigzagging across the full canvas in frantic aborted attempts to find clarity',
    from: 0.55, to: 0.8,
    onEnter(entity, bounds) {
      const margin = 35;
      entity._confEdgeTargets = [
        { x: (bounds.left + bounds.right) / 2, y: bounds.top + margin },
        { x: bounds.right - margin, y: (bounds.top + bounds.bottom) / 2 },
        { x: (bounds.left + bounds.right) / 2, y: bounds.bottom - margin },
        { x: bounds.left + margin, y: (bounds.top + bounds.bottom) / 2 },
        { x: bounds.left + margin, y: bounds.top + margin },
        { x: bounds.right - margin, y: bounds.bottom - margin },
      ];
      entity._confDartTarget = 0;
      entity._confDartTimer = 0;
    },
    update(entity, dt, t) {
      const phaseT = Math.min(1, (t - 0.55) / 0.25);

      entity._confDartTimer += dt;
      const switchRate = 0.2 + (1 - entity.energy) * 0.15;
      if (entity._confDartTimer > switchRate) {
        entity._confDartTimer = 0;
        let newTarget;
        do {
          newTarget = Math.floor(Math.random() * entity._confEdgeTargets.length);
        } while (newTarget === entity._confDartTarget);
        entity._confDartTarget = newTarget;
      }

      const target = entity._confEdgeTargets[entity._confDartTarget];
      const dx = target.x - entity.x;
      const dy = target.y - entity.y;
      const dist = Math.sqrt(dx * dx + dy * dy) || 1;

      const accel = 450 * entity.energy;
      entity.vx += (dx / dist) * accel * dt * 7;
      entity.vy += (dy / dist) * accel * dt * 7;

      entity.vx *= 0.87;
      entity.vy *= 0.87;

      entity.x += entity.vx * dt;
      entity.y += entity.vy * dt;

      const spd = Math.sqrt(entity.vx * entity.vx + entity.vy * entity.vy);
      const stretchAmt = Math.min(spd / 280, 0.32) * entity.energy;
      entity.sx = 1.0 + stretchAmt;
      entity.sy = 1.0 - stretchAmt * 0.5;
      entity.orientation = Math.atan2(entity.vy, entity.vx);

      entity.radius = entity.baseRadius * (0.82 + Math.sin(phaseT * Math.PI * 8) * 0.15);
    },
  }),
  new Phase({
    name: 'stalling',
    description: 'Sluggish drift back toward center with small aborted lunges in random directions that weaken over time, trembling subsides into defeated disoriented stillness',
    from: 0.8, to: 1.0,
    onEnter(entity) {
      entity._confStallLungeTimer = 0;
      entity._confStallLungeDir = Math.random() * Math.PI * 2;
    },
    update(entity, dt, t) {
      const phaseT = Math.min(1, (t - 0.8) / 0.2);
      const center = entity._confCenter;
      const fadeOut = 1.0 - phaseT;

      const dx = center.x - entity.x;
      const dy = center.y - entity.y;
      entity.vx += dx * 2.0 * dt;
      entity.vy += dy * 2.0 * dt;

      entity._confStallLungeTimer += dt;
      const lungeInterval = 0.3 + phaseT * 0.6;
      if (entity._confStallLungeTimer > lungeInterval && fadeOut > 0.15) {
        entity._confStallLungeTimer = 0;
        entity._confStallLungeDir = Math.random() * Math.PI * 2;
        const lungeStrength = 90 * fadeOut * entity.energy;
        entity.vx += Math.cos(entity._confStallLungeDir) * lungeStrength;
        entity.vy += Math.sin(entity._confStallLungeDir) * lungeStrength;
      }

      const damp = 0.90 - phaseT * 0.1;
      entity.vx *= damp;
      entity.vy *= damp;

      entity.x += entity.vx * dt;
      entity.y += entity.vy * dt;

      const time = Date.now() / 1000;
      entity.orientation += Math.sin(time * 4.3) * fadeOut * 1.5 * dt;

      entity.sx = 1.0 + Math.sin(time * 6) * 0.06 * fadeOut;
      entity.sy = 1.0 - Math.sin(time * 6) * 0.04 * fadeOut;

      entity.radius = entity.baseRadius * (0.88 + 0.12 * phaseT);
    },
  }),
], {
  energyFunction: function (t) {
    if (t < 0.3) return 0.35 + 0.45 * (t / 0.3);
    if (t < 0.55) return 0.8 + 0.2 * ((t - 0.3) / 0.25);
    if (t < 0.8) return 1.0;
    return 1.0 - 0.7 * ((t - 0.8) / 0.2);
  }
});