import { Emotion } from '../../../motion-emotion-interfaces/emotion.js';
import { Phase } from '../../../motion-emotion-interfaces/phase.js';

class Effervescence extends Emotion {
  constructor(phases, opts = {}) {
    super(phases, opts);
  }

  decorate(entity, dt) {
    const energy = entity.energy;
    const pulse = Math.sin(entity.t * Math.PI * 14) * 0.07 * energy;
    entity.radius = entity.baseRadius * (1.0 + pulse + energy * 0.15);

    const speed = Math.sqrt(entity.vx * entity.vx + entity.vy * entity.vy);
    if (speed > 20) {
      entity.orientation = Math.atan2(entity.vy, entity.vx);
      const s = Math.min(0.3, speed / 600) * energy;
      entity.sx = 1 + s;
      entity.sy = 1 - s * 0.4;
    } else {
      entity.sx = 1 + pulse * 0.5;
      entity.sy = 1 + pulse * 0.5;
    }
  }
}

/** Starting near the bottom of the canvas, the shape performs a series of small
 * anticipatory bounces with squash-on-contact and stretch-on-release, each bounce
 * growing taller as joy wells up. It then launches into sweeping ascending arcs—
 * bounding leftward to the lower-left quadrant, then rightward and upward to the
 * upper-right, then cresting near the top-center—each parabolic leap wider and
 * higher than the last. At peak altitude the shape traces a wide exuberant
 * elliptical loop through the upper canvas, radius swelling to maximum, velocity
 * stretch elongating it along its flight path. Finally it floats downward in
 * gentle sinusoidal sways of decreasing amplitude, drifting toward the center
 * and settling into a soft rhythmic breathing pulse. Throughout, the circle
 * squash-stretches along its velocity vector and pulses in size, producing a
 * buoyant, balloon-like lightness that reads as irrepressible happiness. */
export const effervescent = new Effervescence([
  new Phase({
    name: 'springUp',
    description: 'Small gathering bounces at bottom center with increasing amplitude, squashing at the base and stretching upward, building momentum like joy welling up',
    from: 0, to: 0.2,
    onEnter(entity, bounds) {
      const cx = (bounds.left + bounds.right) / 2;
      const cy = (bounds.top + bounds.bottom) / 2;
      const w = bounds.right - bounds.left;
      const h = bounds.bottom - bounds.top;
      entity._effCx = cx;
      entity._effCy = cy;
      entity._effW = w;
      entity._effH = h;
      entity._effBounds = bounds;
      entity._effBaseY = bounds.bottom - h * 0.1;
      entity.x = cx;
      entity.y = entity._effBaseY;
      entity.vx = 0;
      entity.vy = 0;
    },
    update(entity, dt, t) {
      const pt = (t - 0) / 0.2;
      const bounceCount = 3;
      const amp = 30 + pt * 110;
      const bounce = -Math.abs(Math.sin(pt * Math.PI * bounceCount)) * amp;
      const targetY = entity._effBaseY + bounce;
      const targetX = entity._effCx + Math.sin(pt * Math.PI) * entity._effW * 0.05;

      const stiffness = 8;
      entity.vx += (targetX - entity.x) * stiffness * dt * 60;
      entity.vy += (targetY - entity.y) * stiffness * dt * 60;
      entity.vx *= 0.85;
      entity.vy *= 0.85;

      const nearBase = 1 - Math.min(1, Math.abs(entity.y - entity._effBaseY) / Math.max(1, amp));
      if (nearBase > 0.8) {
        entity.sy = 0.7 + 0.3 * (1 - nearBase * nearBase);
        entity.sx = 1.3 - 0.3 * (1 - nearBase * nearBase);
      }
    },
  }),

  new Phase({
    name: 'bound',
    description: 'Sweeping ascending arcs across the full canvas width—left then right then up—each parabolic leap higher and wider, like bounding leaps of delight',
    from: 0.2, to: 0.5,
    onEnter(entity, bounds) {
      const w = entity._effW;
      const h = entity._effH;
      entity._effWaypoints = [
        { x: bounds.left + w * 0.15, y: bounds.bottom - h * 0.4 },
        { x: bounds.right - w * 0.15, y: bounds.bottom - h * 0.65 },
        { x: entity._effCx, y: bounds.top + h * 0.15 },
      ];
    },
    update(entity, dt, t) {
      const pt = (t - 0.2) / 0.3;
      const wps = entity._effWaypoints;
      const totalWps = wps.length;
      const wpProgress = pt * totalWps;
      const idx = Math.min(Math.floor(wpProgress), totalWps - 1);
      const wpT = Math.min(1, wpProgress - idx);

      const target = wps[idx];
      const prev = idx > 0 ? wps[idx - 1] : { x: entity._effCx, y: entity._effBaseY };

      const lx = prev.x + (target.x - prev.x) * wpT;
      const ly = prev.y + (target.y - prev.y) * wpT;
      const arcHeight = entity._effH * 0.15 * (1 + idx * 0.3);
      const arcY = ly - Math.sin(wpT * Math.PI) * arcHeight;

      const stiffness = 6;
      entity.vx += (lx - entity.x) * stiffness * dt * 60;
      entity.vy += (arcY - entity.y) * stiffness * dt * 60;
      entity.vx *= 0.88;
      entity.vy *= 0.88;
    },
  }),

  new Phase({
    name: 'exult',
    description: 'Wide exuberant elliptical loop through the upper canvas, sweeping from top-center through the upper-right and upper-left regions with maximum radius and energy',
    from: 0.5, to: 0.75,
    onEnter(entity, bounds) {
      entity._effLoopCx = entity._effCx;
      entity._effLoopCy = bounds.top + entity._effH * 0.35;
      entity._effLoopRx = entity._effW * 0.35;
      entity._effLoopRy = entity._effH * 0.22;
    },
    update(entity, dt, t) {
      const pt = (t - 0.5) / 0.25;
      const angle = -Math.PI * 0.5 + pt * Math.PI * 2;
      const targetX = entity._effLoopCx + Math.cos(angle) * entity._effLoopRx;
      const targetY = entity._effLoopCy + Math.sin(angle) * entity._effLoopRy;

      const stiffness = 10;
      entity.vx += (targetX - entity.x) * stiffness * dt * 60;
      entity.vy += (targetY - entity.y) * stiffness * dt * 60;
      entity.vx *= 0.82;
      entity.vy *= 0.82;
    },
    draw(ctx, entity) {
      const energy = entity.energy;
      if (energy < 0.5) return;
      const alpha = (energy - 0.5) * 0.3;
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 1.5;
      const r = entity.radius * 1.6;
      ctx.beginPath();
      ctx.arc(entity.x, entity.y, r, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    },
  }),

  new Phase({
    name: 'float',
    description: 'Gentle sinusoidal descent toward canvas center, swaying side to side with decreasing amplitude, settling into a warm satisfied breathing pulse',
    from: 0.75, to: 1.0,
    update(entity, dt, t) {
      const pt = (t - 0.75) / 0.25;
      const ease = 1 - pt;
      const targetX = entity._effCx + Math.sin(pt * Math.PI * 3) * entity._effW * 0.15 * ease;
      const targetY = entity._effLoopCy + (entity._effCy - entity._effLoopCy) * pt;

      const stiffness = 4;
      entity.vx += (targetX - entity.x) * stiffness * dt * 60;
      entity.vy += (targetY - entity.y) * stiffness * dt * 60;
      entity.vx *= 0.9;
      entity.vy *= 0.9;

      const breathe = Math.sin(pt * Math.PI * 4) * 0.1 * (1 - pt * 0.5);
      entity.sx = 1 + breathe;
      entity.sy = 1 + breathe;
    },
  }),
], {
  energyFunction: t => {
    if (t < 0.2) return 0.3 + 0.4 * (t / 0.2);
    if (t < 0.5) return 0.7 + 0.3 * ((t - 0.2) / 0.3);
    if (t < 0.75) return 1.0;
    return 1.0 - 0.5 * ((t - 0.75) / 0.25);
  },
});